-- ==== AU_c_stripe_fees_paid ====
CREATE OR REPLACE VIEW default.AU_c_stripe_fees_paid (`month` Nullable(Date), `amount` Float64, `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(created, 'Australia/Sydney')) AS month, (coalesce(sum(fee), 0) + coalesce(sum(multiIf(reporting_category = 'fee', abs(amount), 0)), 0)) / 100. AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions WHERE reporting_category IN ('charge', 'fee') GROUP BY toStartOfMonth(toTimeZone(created, 'Australia/Sydney')) ORDER BY month DESC;

