) AND (JSONExtractString(publicData, 'isRMS') = 'true')), availability_plan_arrays AS (SELECT listing_id, CAST(if(availabilityPlan != '', JSONExtractArrayRaw(assumeNotNull(availabilityPlan), 'entries'), emptyArrayString()), 'Array(String)') AS entries FROM published_listings), availability_entries AS (SELECT listing_id, JSONExtract(entry, 'dayOfWeek', 'String') AS day_of_week_short, coalesce(JSONExtract(entry, 'seats', 'Int32'), 0) AS seats FROM availability_plan_arrays ARRAY JOIN entries AS entry), weekly_plans AS (SELECT listing_id, coalesce(maxIf(seats, day_of_week_short = 'mon'), 0) AS monday, coalesce(maxIf(seats, day_of_week_short = 'tue'), 0) AS tuesday, coalesce(maxIf(seats, day_of_week_short = 'wed'), 0) AS wednesday, coalesce(maxIf(seats, day_of_week_short = 'thu'), 0) AS thursday, coalesce(maxIf(seats, day_of_week_short = 'fri'), 0) AS friday, coalesce(maxIf(seats, day_of_week_short = 'sat'), 0) AS saturday, coalesce(maxIf(seats, day_of_week_short = 'sun'), 0) AS sunday FROM availability_entries GROUP BY listing_id), listing_dates AS (SELECT pl.listing_id, pl.listing_tz, dr.date_value, caseWithExpression(toDayOfWeek(dr.date_value), 1, 'monday', 2, 'tuesday', 3, 'wednesday', 4, 'thursday', 5, 'friday', 6, 'saturday', 7, 'sunday', NULL) AS day_name, caseWithExpression(pl.listing_tz, 'Australia/Melbourne', toDateTime(dr.date_value, 'Australia/Melbourne'), 'Australia/Darwin', toDateTime(dr.date_value, 'Australia/Darwin'), 'Australia/Sydney', toDateTime(dr.date_value, 'Australia/Sydney'), 'Australia/Brisbane', toDateTime(dr.date_value, 'Australia/Brisbane'), 'Australia/Adelaide', toDateTime(dr.date_value, 'Australia/Adelaide'), 'Australia/Hobart', toDateTime(dr.date_value, 'Australia/Hobart'), 'Australia/Perth', toDateTime(dr.date_value, 'Australia/Perth'), toDateTime(dr.date_value, 'Australia/Sydney')) AS day_start, caseWithExpression(pl.listing_tz, 'Australia/Melbourne', toDateTime(dr.date_value, 'Australia/Melbourne') + toIntervalDay(1), 'Australia/Darwin',