ia/Adelaide'), 'Australia/Hobart', toTimeZone(aa.start, 'Australia/Hobart'), 'Australia/Perth', toTimeZone(aa.start, 'Australia/Perth'), toTimeZone(aa.start, 'Australia/Sydney')) AS block_start, caseWithExpression(pl.listing_tz, 'Australia/Melbourne', toTimeZone(aa.end, 'Australia/Melbourne'), 'Australia/Darwin', toTimeZone(aa.end, 'Australia/Darwin'), 'Australia/Sydney', toTimeZone(aa.end, 'Australia/Sydney'), 'Australia/Brisbane', toTimeZone(aa.end, 'Australia/Brisbane'), 'Australia/Adelaide', toTimeZone(aa.end, 'Australia/Adelaide'), 'Australia/Hobart', toTimeZone(aa.end, 'Australia/Hobart'), 'Australia/Perth', toTimeZone(aa.end, 'Australia/Perth'), toTimeZone(aa.end, 'Australia/Sydney')) AS block_end, aa.type FROM combined_availability AS aa INNER JOIN published_listings AS pl ON aa.listing_id = pl.listing_id), flex_plus_listings AS (SELECT al.id AS listing_id, toDate(parseDateTimeBestEffortOrNull(fb.`Contract/Booking Start Date`)) AS fp_start_date, if(upper(trimBoth(fb.`Contract/Booking End Date`)) = 'ONGOING', toDate(now()) + 60, toDate(parseDateTimeBestEffortOrNull(fb.`Contract/Booking End Date`))) AS fp_end_date FROM default.flexplus_bookings AS fb LEFT JOIN default.au_listings AS al ON upper(JSONExtractString(al.publicData, 'license_plate_number')) = fb.Rego WHERE (fb.Rego != '') AND (al.id IS NOT NULL)), flex_plus_check AS (SELECT DISTINCT ldw.listing_id, ldw.date_value, 1 AS is_flex_plus FROM listing_dates_with_weekly AS ldw INNER JOIN flex_plus_listings AS fpl ON (ldw.listing_id = fpl.listing_id) AND (ldw.date_value >= fpl.fp_start_date) AND (ldw.date_value <= fpl.fp_end_date) WHERE (fpl.fp_start_date IS NOT NULL) AND (fpl.fp_end_date IS NOT NULL)), daily_block_minutes AS (SELECT ldw.listing_id, ldw.date_value, sum(multiIf(ab.type != 'BOOKING', 0, ab.block_start IS NULL, 0, ab.block_end <= ldw.day_start, 0, ab.block_start >= ldw.day_end, 0, CAST(least(ab.block_end, ldw.day_end) - greatest(ab.block_start, ldw.day_start), 'Int64') / 60)) AS booked_minutes, sum(multiIf(ab.type != 'BLOCK', 0, ab.block_start IS NULL, 0, ab.block_end <= ldw.day_start, 0, ab.block_start >= ldw.day_end, 0, CAST(least(ab.block_end, ldw.day_end) - greatest(ab.block_start, ldw.day_start), 'Int64') / 60)) AS blocked_minutes FROM listing_dates_with_weekly AS ldw LEFT JOIN availability_blocks AS ab ON (ldw.listing_id = ab.listing_id) AND (ab.block_end > ldw.day_start) AND (ab.block_start < ldw.day_end) GROUP BY ldw.listing_id, ldw.date_value), daily_status AS (SELECT dbm.listing_id, dbm.date_value, multiIf(fpc.is_flex_plus = 1, 'Flex+', dbm.booked_minutes >= 1440, 'Fully booked', dbm.booked_minutes > 0, 'Partially booked', dbm.blocked_minutes >= 1440, 'Fully Blocked', dbm.blocked_minutes > 0, 'Partially blocked', 'Idle') AS day_status FROM daily_block_minutes AS dbm LEFT JOIN flex_plus_check AS fpc ON (dbm.listing_id = fpc.listing_id) AND (dbm.date_value = fpc.date_value)), listing_today AS (SELECT listing_id, caseWithExpression(listing_tz, 'Australia/Melbourne', toDate(toTimeZone(now(), 'Australia/Melbourne')), 'Australia/Darwin', toDate(toTimeZone(now(), 'Australia/Darwin')), 'Australia/Sydney', toDate(toTimeZone(now(), 'Australia/Sydney')), 'Australia/Brisbane', toDate(toTimeZone(now(), 'Australia/Brisbane')), 'Australia/Adelaide', toDate(toTimeZone(now(), 'Australia/Adelaide')), 'Australia/Hobart', toDate(toTimeZone(now(), 'Australia/Hobart')), 'Australia/Perth', toDate(toTimeZone(now(), 'Australia/Perth')), toDate(toTimeZone(now(), 'Australia/Sydney'))) AS local_today FROM published_listings) SELECT ds.listing_id, upper(JSONExtractString(al.publicData, 'license_plate_number')) AS license_plate_number, JSONExtractString(JSONExtractString(al.publicData, 'location'), 'state') AS state, al.state AS listing_status, JSONExtractBool(al.metadata, 'live') AS live, JSONExtractString(JSONExtractString(al.metadata, 'rmsData'), 'actualHostName') AS actualHostName, JSONExtractString(JSONExtractString(JSONExtractString(al.publicData, 'deviceManagement'), 