-- ==== v_AU_a_cost_fuel_payout ====
CREATE OR REPLACE VIEW default.v_AU_a_cost_fuel_payout (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType = 'fuel_refund') AND (payoutAmount > 0) AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_cost_fuel_refund_to_guest ====
CREATE OR REPLACE VIEW default.v_AU_a_cost_fuel_refund_to_guest (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month_year AS month, round(abs(sum(amount)), 2) AS amount, sum(row_count) AS row_count FROM default.v_AU_c_fuel_refunds GROUP BY month_year HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_cost_late_return ====
CREATE OR REPLACE VIEW default.v_AU_a_cost_late_return (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType IN ('late_return')) AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_fuel_charged_to_host ====
CREATE OR REPLACE VIEW default.v_AU_a_fuel_charged_to_host (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, round(sum((-payoutAmount) / 100.), 2) AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType IN ('fuel_charge', 'fuel_refund')) AND (payoutAmount < 0) AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_host_discounts ====
CREATE OR REPLACE VIEW default.v_AU_a_host_discounts (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType = 'long_term_discount') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_host_flexplus_payout ====
CREATE OR REPLACE VIEW default.v_AU_a_host_flexplus_payout (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, sum(payoutAmount) / 100. AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType = 'flexplus') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_host_incidentals_cleanliness ====
CREATE OR REPLACE VIEW default.v_AU_a_host_incidentals_cleanliness (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType = 'cleanliness') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_host_incidentals_damage ====
CREATE OR REPLACE VIEW default.v_AU_a_host_incidentals_damage (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType = 'damage') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_host_incidentals_excess_mileage ====
CREATE OR REPLACE VIEW default.v_AU_a_host_incidentals_excess_mileage (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType = 'excess_mileage') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_host_incidentals_tolls ====
CREATE OR REPLACE VIEW default.v_AU_a_host_incidentals_tolls (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType = 'tolls') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_host_misc_charge_collected ====
CREATE OR REPLACE VIEW default.v_AU_a_host_misc_charge_collected (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, sum(payoutAmount) / 100. AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType = 'misc_charge') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_host_payout_regular_p2p ====
CREATE OR REPLACE VIEW default.v_AU_a_host_payout_regular_p2p (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT multiIf((pe.tripId IS NOT NULL) AND (JSONExtractUInt(mt.protectedData, 'bookingDisplayEnd') > 0) AND match(toString(JSONExtractUInt(mt.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), toStartOfMonth(fromUnixTimestamp(toUInt32(JSONExtractUInt(mt.protectedData, 'bookingDisplayEnd') / 1000))), toStartOfMonth(pe.createdAt)) AS month, round(sum(pe.payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_payout_entries AS pe LEFT JOIN default.v_host_mechanism_map AS m ON (m.market = 'AU') AND (m.host_id = pe.hostId) LEFT JOIN default.au_transactions AS mt ON pe.tripId = mt.id WHERE (pe.payoutType IN ('duration', 'distance', 'trip')) AND ((pe.finance_status IS NULL) OR (pe.finance_status != 'Under Review')) AND ((pe.tripStatus IS NULL) OR (pe.tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) AND (ifNull(m.mechanism, 'p2p') = 'p2p') GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_host_referral_payout ====
CREATE OR REPLACE VIEW default.v_AU_a_host_referral_payout (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, sum(payoutAmount) / 100. AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType = 'referral') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_host_subscription_collected ====
CREATE OR REPLACE VIEW default.v_AU_a_host_subscription_collected (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType = 'subscription') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_host_trip_earnings_rms ====
CREATE OR REPLACE VIEW default.v_AU_a_host_trip_earnings_rms (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(amt), 2) AS amount, sum(rc) AS row_count FROM (SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, payoutAmount / 100. AS amt, 1 AS rc FROM default.au_payout_entries WHERE (payoutType = 'rms') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) UNION ALL SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, payoutAmount / 100. AS amt, 1 AS rc FROM default.au_payout_entries WHERE (payoutType = 'misc_payout') AND (positionCaseInsensitive(ifNull(description, ''), 'rms') > 0) AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')))) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_AU_a_incidentals_classified ====
CREATE OR REPLACE VIEW default.v_AU_a_incidentals_classified (`month` Nullable(Date), `invoice_id` String, `descr` String, `amount` Float64, `gst_incl` Float64, `account_code` String) AS WITH (SELECT groupArray(keyword) FROM (SELECT keyword, account_code FROM default.incidentals_desc_lookup ORDER BY priority ASC)) AS kw, (SELECT groupArray(account_code) FROM (SELECT keyword, account_code FROM default.incidentals_desc_lookup ORDER BY priority ASC)) AS ac SELECT toStartOfMonth(toTimezone(i.created, 'Australia/Sydney')) AS month, i.id AS invoice_id, JSONExtractString(line, 'description') AS descr, toFloat64(JSONExtractInt(line, 'amount')) / 100. AS amount, arraySum(x -> (toFloat64(JSONExtractInt(x, 'amount')) / 100.), JSONExtractArrayRaw(JSONExtractString(line, 'tax_amounts'))) AS gst_incl, if(arrayFirstIndex(x -> (position(lower(JSONExtractString(line, 'description')), x) > 0), kw) = 0, '4025', ac[arrayFirstIndex(x -> (position(lower(JSONExtractString(line, 'description')), x) > 0), kw)]) AS account_code FROM default.au_stripe_invoices AS i ARRAY JOIN JSONExtractArrayRaw(JSONExtractString(assumeNotNull(i.lines), 'data')) AS line WHERE (i.subscription IS NULL) AND ((JSONExtractString(i.metadata, 'distanceTransactionId') IS NULL) OR (JSONExtractString(i.metadata, 'distanceTransactionId') = '')) AND (i.status NOT IN ('void', 'draft'));

-- ==== v_AU_a_incidentals_cleaning_invoiced ====
CREATE OR REPLACE VIEW default.v_AU_a_incidentals_cleaning_invoiced (`month` Nullable(Date), `amount` Float64, `row_count` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, count(*) AS row_count FROM default.v_AU_a_incidentals_classified WHERE account_code = '4022' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_AU_a_incidentals_damage_invoiced ====
