CREATE OR REPLACE VIEW default.v_AU_a_incidentals_other_invoiced (`month` Nullable(Date), `amount` Float64, `row_count` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, count(*) AS row_count FROM default.v_AU_a_incidentals_classified WHERE account_code = '4025' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_AU_a_incidentals_paginated_hold ====
CREATE OR REPLACE VIEW default.v_AU_a_incidentals_paginated_hold (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(hold_amount), 2) AS amount, count() AS row_count FROM (SELECT toStartOfMonth(toTimezone(i.created, 'Australia/Sydney')) AS month, i.id AS invoice_id, (i.amount_due / 100.) - arraySum(x -> (toFloat64(JSONExtractInt(x, 'amount')) / 100.), JSONExtractArrayRaw(JSONExtractString(assumeNotNull(i.lines), 'data'))) AS hold_amount FROM default.au_stripe_invoices AS i WHERE (i.subscription IS NULL) AND ((JSONExtractString(i.metadata, 'distanceTransactionId') IS NULL) OR (JSONExtractString(i.metadata, 'distanceTransactionId') = '')) AND (i.status NOT IN ('void', 'draft')) AND (JSONExtractBool(assumeNotNull(i.lines), 'has_more') = 1)) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

