-- ==== v_AU_a_misc_payout_classified ====
CREATE OR REPLACE VIEW default.v_AU_a_misc_payout_classified (`month` Nullable(Date), `payoutAmount` Nullable(Int32), `account_code` String) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, payoutAmount, multiIf(positionCaseInsensitive(d, 'toll') > 0, '5020', positionCaseInsensitive(d, 'tow') > 0, '5033', (positionCaseInsensitive(d, 'afca') > 0) OR (positionCaseInsensitive(d, 'damage') > 0) OR (positionCaseInsensitive(d, 'repair') > 0) OR (positionCaseInsensitive(d, 'storage') > 0) OR (positionCaseInsensitive(d, 'key ') > 0) OR (positionCaseInsensitive(d, 'key replace') > 0), '5021', positionCaseInsensitive(d, 'sticker') > 0, '5041', (positionCaseInsensitive(d, 'superhost') > 0) OR (positionCaseInsensitive(d, 'super host') > 0), '5040', positionCaseInsensitive(d, 'downtime') > 0, '5043', positionCaseInsensitive(d, 'parking') > 0, '5060', (positionCaseInsensitive(d, 'goodwill') > 0) OR (positionCaseInsensitive(d, 'compensat') > 0), '5042', (positionCaseInsensitive(d, 'correct distance') > 0) OR (positionCaseInsensitive(d, 'missing distance') > 0) OR (positionCaseInsensitive(d, 'rebilling') > 0) OR (positionCaseInsensitive(d, 'gap hours') > 0) OR (positionCaseInsensitive(d, 'additional days') > 0) OR (positionCaseInsensitive(d, 'additional earnings') > 0) OR (positionCaseInsensitive(d, 'trip additional') > 0), '5000', '5042') AS account_code FROM (SELECT payoutAmount, createdAt, lowerUTF8(trimBoth(ifNull(description, ''))) AS d FROM default.au_payout_entries WHERE (payoutType = 'misc_payout') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))));

