-- ==== v_AU_a_subscription_device_invoiced ====
CREATE OR REPLACE VIEW default.v_AU_a_subscription_device_invoiced (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimezone(i.created, 'Australia/Sydney')) AS month, sum(i.amount_due) / 100. AS amount, count(*) AS row_count FROM default.au_stripe_invoices AS i WHERE (i.subscription IS NOT NULL) AND (i.status NOT IN ('void', 'draft')) AND ((NOT ((JSONExtractString(i.metadata, 'payment_plan') != '') OR (lower(i.lines) LIKE '%payment plan%'))) AND (NOT (lower(i.lines) LIKE '%flex+%')) AND (NOT (lower(i.lines) LIKE '%insur%')) AND ((lower(i.lines) LIKE '%mates%') OR (lower(i.lines) LIKE '%drive lah go%') OR (lower(i.lines) LIKE '%dl go%') OR (lower(i.lines) LIKE '%dlg%') OR (lower(i.lines) LIKE '%gps%') OR (lower(i.lines) LIKE '%lockbox%') OR (lower(i.lines) LIKE '%keyless%') OR (lower(i.lines) LIKE '%byod%'))) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_AU_a_subscription_flexplus_invoiced ====
CREATE OR REPLACE VIEW default.v_AU_a_subscription_flexplus_invoiced (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimezone(i.created, 'Australia/Sydney')) AS month, sum(i.amount_due) / 100. AS amount, count(*) AS row_count FROM default.au_stripe_invoices AS i WHERE (i.subscription IS NOT NULL) AND (i.status NOT IN ('void', 'draft')) AND ((NOT ((JSONExtractString(i.metadata, 'payment_plan') != '') OR (lower(i.lines) LIKE '%payment plan%'))) AND (lower(i.lines) LIKE '%flex+%')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_AU_a_subscription_insurance_invoiced ====
CREATE OR REPLACE VIEW default.v_AU_a_subscription_insurance_invoiced (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimezone(i.created, 'Australia/Sydney')) AS month, sum(i.amount_due) / 100. AS amount, count(*) AS row_count FROM default.au_stripe_invoices AS i WHERE (i.subscription IS NOT NULL) AND (i.status NOT IN ('void', 'draft')) AND ((NOT ((JSONExtractString(i.metadata, 'payment_plan') != '') OR (lower(i.lines) LIKE '%payment plan%'))) AND (NOT (lower(i.lines) LIKE '%flex+%')) AND (lower(i.lines) LIKE '%insur%')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_AU_a_subscription_other_invoiced ====
CREATE OR REPLACE VIEW default.v_AU_a_subscription_other_invoiced (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimezone(i.created, 'Australia/Sydney')) AS month, sum(i.amount_due) / 100. AS amount, count(*) AS row_count FROM default.au_stripe_invoices AS i WHERE (i.subscription IS NOT NULL) AND (i.status NOT IN ('void', 'draft')) AND ((NOT ((JSONExtractString(i.metadata, 'payment_plan') != '') OR (lower(i.lines) LIKE '%payment plan%'))) AND (NOT (lower(i.lines) LIKE '%flex+%')) AND (NOT (lower(i.lines) LIKE '%insur%')) AND (NOT ((lower(i.lines) LIKE '%mates%') OR (lower(i.lines) LIKE '%drive lah go%') OR (lower(i.lines) LIKE '%dl go%') OR (lower(i.lines) LIKE '%dlg%') OR (lower(i.lines) LIKE '%gps%') OR (lower(i.lines) LIKE '%lockbox%') OR (lower(i.lines) LIKE '%keyless%') OR (lower(i.lines) LIKE '%byod%')))) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_AU_a_trip_distance_invoiced ====
CREATE OR REPLACE VIEW default.v_AU_a_trip_distance_invoiced (`month_year` Nullable(Date), `invoice_count` UInt64, `total_invoiced` Nullable(Float64), `total_paid` Nullable(Float64), `total_remaining` Nullable(Float64)) AS SELECT toStartOfMonth(toTimezone(i.created, 'Australia/Sydney')) AS month_year, count(*) AS invoice_count, sum(i.total) / 100. AS total_invoiced, sum(i.amount_paid) / 100. AS total_paid, sum(i.amount_remaining) / 100. AS total_remaining FROM default.au_stripe_invoices AS i WHERE (i.status NOT IN ('void', 'draft')) AND (i.created IS NOT NULL) AND ((i.subscription IS NULL) OR (i.subscription = '')) AND (JSONExtractString(i.metadata, 'distanceTransactionId') IS NOT NULL) AND (JSONExtractString(i.metadata, 'distanceTransactionId') != '') GROUP BY month_year HAVING month_year < toStartOfMonth(today()) ORDER BY month_year DESC;

-- ==== v_AU_a_trip_revenue_p2p ====
CREATE OR REPLACE VIEW default.v_AU_a_trip_revenue_p2p (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimezone(multiIf((JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') > 0) AND match(toString(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), fromUnixTimestamp(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000)), ((JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') IS NULL) OR (JSONExtractString(txn.protectedData, 'bookingDisplayEnd') = 'NaN')) AND (JSONExtractString(txn.protectedData, 'parentTxId') IS NOT NULL) AND (JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') IS NOT NULL) AND match(toString(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), fromUnixTimestamp(toUInt32(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') / 1000)), bt.created), 'Australia/Sydney')) AS month, round(sum(bt.amount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_charges AS c ON bt.source = c.id LEFT JOIN default.au_stripe_charges AS cm ON c.id = cm.id INNER JOIN default.au_transactions AS txn ON JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = txn.id LEFT JOIN default.au_transactions AS parent_txn ON JSONExtractString(txn.protectedData, 'parentTxId') = parent_txn.id LEFT JOIN default.v_host_mechanism_map AS m ON (txn.providerId = m.host_id) AND (m.market = 'AU') WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') IS NOT NULL) AND (txn.processName NOT IN ('distance-charging', 'unpaid-dues')) AND (bt.description NOT ILIKE '%Verifications Charge%') AND (bt.description NOT ILIKE '%Security deposit%') AND (bt.description NOT ILIKE '%Refundable Deposit%') AND (((JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') IS NOT NULL) AND match(toString(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$')) OR ((JSONExtractString(txn.protectedData, 'parentTxId') IS NOT NULL) AND (JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') IS NOT NULL) AND match(toString(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$')) OR (bt.created IS NOT NULL)) AND ((m.mechanism = 'p2p') OR (m.mechanism IS NULL)) GROUP BY month HAVING month < toStartOfMonth(now()) ORDER BY month DESC;

-- ==== v_AU_a_trip_revenue_rms ====
CREATE OR REPLACE VIEW default.v_AU_a_trip_revenue_rms (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimezone(multiIf((JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') > 0) AND match(toString(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), fromUnixTimestamp(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000)), ((JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') IS NULL) OR (JSONExtractString(txn.protectedData, 'bookingDisplayEnd') = 'NaN')) AND (JSONExtractString(txn.protectedData, 'parentTxId') IS NOT NULL) AND (JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') IS NOT NULL) AND match(toString(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), fromUnixTimestamp(toUInt32(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') / 1000)), bt.created), 'Australia/Sydney')) AS month, round(sum(bt.amount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_charges AS c ON bt.source = c.id LEFT JOIN default.au_stripe_charges AS cm ON c.id = cm.id INNER JOIN default.au_transactions AS txn ON JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = txn.id LEFT JOIN default.au_transactions AS parent_txn ON JSONExtractString(txn.protectedData, 'parentTxId') = parent_txn.id LEFT JOIN default.v_host_mechanism_map AS m ON (txn.providerId = m.host_id) AND (m.market = 'AU') WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') IS NOT NULL) AND (txn.processName NOT IN ('distance-charging', 'unpaid-dues')) AND (bt.description NOT ILIKE '%Verifications Charge%') AND (bt.description NOT ILIKE '%Security deposit%') AND (bt.description NOT ILIKE '%Refundable Deposit%') AND (((JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') IS NOT NULL) AND match(toString(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$')) OR ((JSONExtractString(txn.protectedData, 'parentTxId') IS NOT NULL) AND (JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') IS NOT NULL) AND match(toString(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$')) OR (bt.created IS NOT NULL)) AND (m.mechanism = 'rms') GROUP BY month HAVING month < toStartOfMonth(now()) ORDER BY month DESC;

-- ==== v_AU_c_customer_deposits_received ====
CREATE OR REPLACE VIEW default.v_AU_c_customer_deposits_received (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(created, 'Australia/Sydney')) AS month, sum(bt.amount) / 100. AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_charges AS c ON bt.source = c.id WHERE (reporting_category = 'charge') AND (bt.amount > 0) AND ((description ILIKE '%Refundable deposit%') OR (description ILIKE '%Security deposit%') OR (description ILIKE '%Deposit%')) GROUP BY toStartOfMonth(toTimeZone(created, 'Australia/Sydney')) HAVING month < toStartOfMonth(today());

-- ==== v_AU_c_deposit_internal_transfer ====
CREATE OR REPLACE VIEW default.v_AU_c_deposit_internal_transfer (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month, round(-sum(bt.amount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_transfers AS t ON t.id = bt.source WHERE (bt.reporting_category IN ('transfer', 'transfer_reversal')) AND (t.destination = 'acct_1JkKmQQWb9mOwfae') GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_AU_c_deposit_refunds ====
CREATE OR REPLACE VIEW default.v_AU_c_deposit_refunds (`month_year` Nullable(Date), `amount` Nullable(Float64), `total_fees` Nullable(Float64), `net_amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month_year, sum(bt.amount) / 100. AS amount, sum(bt.fee) / 100. AS total_fees, sum(bt.net) / 100. AS net_amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_refunds AS r ON bt.source = r.id INNER JOIN default.au_stripe_charges AS c ON r.charge = c.id INNER JOIN default.au_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.au_stripe_refunds AS rm ON r.id = rm.id WHERE (bt.reporting_category = 'refund') AND (bt.amount < 0) AND ((JSONExtractString(rm.metadata, 'category') = '') OR (JSONExtractString(rm.metadata, 'category') != 'fuelrefund')) AND (bt.description LIKE '%Refundable deposit%') AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') != '') GROUP BY toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) HAVING month_year < toStartOfMonth(today()) ORDER BY month_year DESC;

-- ==== v_AU_c_disputes ====
CREATE OR REPLACE VIEW default.v_AU_c_disputes (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month, round(-sum(bt.amount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt WHERE bt.reporting_category IN ('dispute', 'dispute_reversal') GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_AU_c_fuel_refunds ====
CREATE OR REPLACE VIEW default.v_AU_c_fuel_refunds (`month_year` Nullable(Date), `amount` Nullable(Float64), `total_fees` Nullable(Float64), `net_amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month_year, sum(bt.amount) / 100. AS amount, sum(bt.fee) / 100. AS total_fees, sum(bt.net) / 100. AS net_amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_refunds AS r ON bt.source = r.id INNER JOIN default.au_stripe_refunds AS rm ON (r.id = rm.id) AND (JSONExtractString(rm.metadata, 'category') = 'fuelrefund') WHERE (1 = 1) AND (bt.reporting_category = 'refund') AND (bt.amount < 0) GROUP BY toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) HAVING month_year < toStartOfMonth(today()) ORDER BY month_year DESC;

-- ==== v_AU_c_host_rms_internal_clearing ====
CREATE OR REPLACE VIEW default.v_AU_c_host_rms_internal_clearing (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month, round(-sum(bt.amount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_transfers AS t ON t.id = bt.source WHERE (bt.reporting_category IN ('transfer', 'transfer_reversal')) AND (t.destination IN (SELECT id FROM default.au_stripe_connected_accounts WHERE match(email, 'rms[0-9]') OR (email ILIKE '%flexplus%') OR (email ILIKE '%caretaker%'))) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_AU_c_host_transfers ====
CREATE OR REPLACE VIEW default.v_AU_c_host_transfers (`month` Nullable(Date), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `transfer_count` UInt64, `transfers` UInt64, `transfer_reversals` UInt64, `application_fees` UInt64, `application_fee_refunds` UInt64, `days_with_transfers` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month, round(sum(bt.amount / 100.), 2) AS amount, round(sum(bt.fee / 100.), 2) AS fee, round(sum(bt.net / 100.), 2) AS net_amount, count(*) AS transfer_count, countIf(bt.reporting_category = 'transfer') AS transfers, countIf(bt.reporting_category = 'transfer_reversal') AS transfer_reversals, countIf(bt.reporting_category = 'platform_earning') AS application_fees, countIf(bt.reporting_category = 'platform_earning_refund') AS application_fee_refunds, uniqExact(toDate(toTimeZone(bt.created, 'Australia/Sydney'))) AS days_with_transfers FROM default.au_stripe_balance_transactions AS bt LEFT JOIN default.au_stripe_transfers AS t ON t.id = bt.source WHERE (bt.reporting_category IN ('transfer', 'transfer_reversal', 'platform_earning', 'platform_earning_refund')) AND (NOT ((bt.reporting_category IN ('transfer', 'transfer_reversal')) AND ((t.destination IN (SELECT id FROM default.au_stripe_connected_accounts WHERE match(email, 'rms[0-9]') OR (email ILIKE '%flexplus%') OR (email ILIKE '%caretaker%'))) OR (t.destination IN ('acct_1EhuMGAcVqeggTlg', 'acct_1JkKmQQWb9mOwfae'))))) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_AU_c_incidentals_invoice_paid ====
CREATE OR REPLACE VIEW default.v_AU_c_incidentals_invoice_paid (`month_year` Nullable(Date), `transaction_count` UInt64, `total_amount` Nullable(Float64), `total_fees` Nullable(Float64), `net_amount` Nullable(Float64)) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month_year, count(*) AS transaction_count, sum(bt.amount) / 100. AS total_amount, sum(bt.fee) / 100. AS total_fees, sum(bt.net) / 100. AS net_amount FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_charges AS c ON bt.source = c.id LEFT JOIN default.au_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.au_transactions AS txn ON JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = txn.id LEFT JOIN default.au_stripe_invoices AS i ON c.invoice = i.id LEFT JOIN default.au_stripe_invoices AS im_dist ON i.id = im_dist.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (((c.invoice IS NOT NULL) AND ((i.subscription IS NULL) OR (i.subscription = '')) AND (JSONExtractString(im_dist.metadata, 'distanceTransactionId') = '')) OR ((c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') != '') AND (txn.processName = 'unpaid-dues'))) AND (lower(bt.description) NOT LIKE '%verifications charge%') AND (lower(bt.description) NOT LIKE '%security deposit%') AND (lower(bt.description) NOT LIKE '%refundable deposit%') GROUP BY toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) HAVING month_year < toStartOfMonth(today()) ORDER BY month_year DESC;

-- ==== v_AU_c_invoice_payment_refunds ====
CREATE OR REPLACE VIEW default.v_AU_c_invoice_payment_refunds (`month_year` Nullable(Date), `amount` Nullable(Float64), `total_fees` Nullable(Float64), `net_amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month_year, sum(bt.amount) / 100. AS amount, sum(bt.fee) / 100. AS total_fees, sum(bt.net) / 100. AS net_amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_refunds AS r ON bt.source = r.id INNER JOIN default.au_stripe_charges AS c ON r.charge = c.id LEFT JOIN default.au_stripe_refunds AS rm ON r.id = rm.id WHERE (1 = 1) AND (bt.reporting_category = 'refund') AND (bt.amount < 0) AND ((JSONExtractString(rm.metadata, 'category') = '') OR (JSONExtractString(rm.metadata, 'category') != 'fuelrefund')) AND ((lower(bt.description) ILIKE '%invoice%') OR (lower(bt.description) ILIKE '%payment%')) GROUP BY toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) HAVING month_year < toStartOfMonth(today()) ORDER BY month_year DESC;

-- ==== v_AU_c_misc_charges_collected ====
CREATE OR REPLACE VIEW default.v_AU_c_misc_charges_collected (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month, round(sum(bt.amount) / 100., 2) AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_charges AS c ON bt.source = c.id LEFT JOIN default.au_stripe_charges AS cm ON c.id = cm.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = '') AND (lower(ifNull(bt.description, '')) NOT LIKE '%verifications charge%') AND (lower(ifNull(bt.description, '')) NOT LIKE '%security deposit%') AND (lower(ifNull(bt.description, '')) NOT LIKE '%refundable deposit%') GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_AU_c_stripe_fees_paid ====
CREATE OR REPLACE VIEW default.v_AU_c_stripe_fees_paid (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(created, 'Australia/Sydney')) AS month, round((sum(if(reporting_category != 'connect_reserved_funds', fee, 0)) + sum(if(reporting_category = 'fee', abs(amount), 0))) / 100., 2) AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_AU_c_stripe_payouts ====
CREATE OR REPLACE VIEW default.v_AU_c_stripe_payouts (`balance_transaction_id` String, `payout_source_id` Nullable(String), `transaction_date` Nullable(DateTime('Australia/Sydney')), `payout_description` Nullable(String), `transaction_status` Nullable(String), `transaction_type` Nullable(String), `net_amount_dollars` Nullable(Float64), `payout_fee_dollars` Nullable(Float64), `gross_amount_dollars` Nullable(Float64), `currency` Nullable(String), `debit_account_name` String, `credit_account_name` String, `credit_account_id` UInt8, `journal_amount` Nullable(Float64), `entry_type` String, `source_view` String, `created_sydney` Nullable(DateTime('Australia/Sydney')), `view_created_at` DateTime) AS SELECT bt.id AS balance_transaction_id, bt.source AS payout_source_id, toTimeZone(bt.created, 'Australia/Sydney') AS transaction_date, bt.description AS payout_description, bt.status AS transaction_status, bt.type AS transaction_type, bt.net / 100. AS net_amount_dollars, bt.fee / 100. AS payout_fee_dollars, bt.amount / 100. AS gross_amount_dollars, bt.currency, 'Main Business Bank Account' AS debit_account_name, 'Stripe - Clearing Account' AS credit_account_name, 169 AS credit_account_id, abs(bt.net / 100.) AS journal_amount, 'stripe_payout' AS entry_type, 'C_stripe_payouts' AS source_view, toTimeZone(bt.created, 'Australia/Sydney') AS created_sydney, now() AS view_created_at FROM default.au_stripe_balance_transactions AS bt WHERE ((bt.type = 'payout') OR (bt.type = 'payout_cancel')) AND (bt.net IS NOT NULL) AND (bt.net != 0) AND (bt.status = 'available') ORDER BY bt.created DESC, bt.id DESC;

-- ==== v_AU_c_stripe_platform_adjustments ====
CREATE OR REPLACE VIEW default.v_AU_c_stripe_platform_adjustments (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(created, 'Australia/Sydney')) AS month, round(-sum(amount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions WHERE reporting_category IN ('refund_failure', 'connect_collection_transfer', 'charge_failure') GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_AU_c_stripe_reserve ====
CREATE OR REPLACE VIEW default.v_AU_c_stripe_reserve (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(created) AS month, round(-sum(amount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions WHERE reporting_category = 'connect_reserved_funds' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_AU_c_subscription_invoice_paid ====
CREATE OR REPLACE VIEW default.v_AU_c_subscription_invoice_paid (`month_year` Nullable(Date), `transaction_count` UInt64, `total_amount` Nullable(Float64), `total_fees` Nullable(Float64), `net_amount` Nullable(Float64)) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month_year, count(*) AS transaction_count, sum(bt.amount) / 100. AS total_amount, sum(bt.fee) / 100. AS total_fees, sum(bt.net) / 100. AS net_amount FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_charges AS c ON bt.source = c.id INNER JOIN default.au_stripe_invoices AS i ON c.invoice = i.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NOT NULL) AND (i.subscription IS NOT NULL) AND (i.subscription != '') AND (lower(bt.description) NOT LIKE '%verifications charge%') AND (lower(bt.description) NOT LIKE '%security deposit%') AND (lower(bt.description) NOT LIKE '%refundable deposit%') GROUP BY toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) HAVING month_year < toStartOfMonth(today()) ORDER BY month_year DESC;

-- ==== v_AU_c_subscription_refunds_device ====
CREATE OR REPLACE VIEW default.v_AU_c_subscription_refunds_device (`month_year` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month_year, round(sum(bt.amount) / 100., 2) AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_refunds AS r ON bt.source = r.id INNER JOIN default.au_stripe_charges AS c ON r.charge = c.id LEFT JOIN default.au_stripe_invoices AS i ON c.invoice = i.id LEFT JOIN default.au_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.au_stripe_refunds AS rm ON r.id = rm.id WHERE (bt.reporting_category = 'refund') AND (bt.amount < 0) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = '') AND ((JSONExtractString(rm.metadata, 'category') = '') OR (JSONExtractString(rm.metadata, 'category') != 'fuelrefund')) AND (lower(bt.description) NOT LIKE '%invoice%') AND (lower(bt.description) NOT LIKE '%payment%') AND (NOT (lower(coalesce(i.lines, '')) LIKE '%insur%')) GROUP BY month_year HAVING month_year < toStartOfMonth(today()) ORDER BY month_year DESC;

-- ==== v_AU_c_subscription_refunds_insurance ====
CREATE OR REPLACE VIEW default.v_AU_c_subscription_refunds_insurance (`month_year` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month_year, round(sum(bt.amount) / 100., 2) AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_refunds AS r ON bt.source = r.id INNER JOIN default.au_stripe_charges AS c ON r.charge = c.id LEFT JOIN default.au_stripe_invoices AS i ON c.invoice = i.id LEFT JOIN default.au_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.au_stripe_refunds AS rm ON r.id = rm.id WHERE (bt.reporting_category = 'refund') AND (bt.amount < 0) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = '') AND ((JSONExtractString(rm.metadata, 'category') = '') OR (JSONExtractString(rm.metadata, 'category') != 'fuelrefund')) AND (lower(bt.description) NOT LIKE '%invoice%') AND (lower(bt.description) NOT LIKE '%payment%') AND (lower(i.lines) LIKE '%insur%') GROUP BY month_year HAVING month_year < toStartOfMonth(today()) ORDER BY month_year DESC;

-- ==== v_AU_c_trip_cash_collected ====
CREATE OR REPLACE VIEW default.v_AU_c_trip_cash_collected (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month, sum(bt.amount) / 100. AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_charges AS c ON bt.source = c.id LEFT JOIN default.au_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.au_transactions AS txn ON JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = txn.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') != '') AND (txn.processName NOT IN ('distance-charging', 'unpaid-dues')) AND (lower(bt.description) NOT LIKE '%verifications charge%') AND (lower(bt.description) NOT LIKE '%security deposit%') AND (lower(bt.description) NOT LIKE '%refundable deposit%') GROUP BY toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_AU_c_trip_distance_cash_collected ====
CREATE OR REPLACE VIEW default.v_AU_c_trip_distance_cash_collected (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month, sum(bt.amount) / 100. AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_charges AS c ON bt.source = c.id LEFT JOIN default.au_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.au_transactions AS txn ON JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = txn.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') != '') AND (txn.processName = 'distance-charging') AND (lower(bt.description) NOT LIKE '%verifications charge%') AND (lower(bt.description) NOT LIKE '%security deposit%') AND (lower(bt.description) NOT LIKE '%refundable deposit%') GROUP BY toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_AU_c_trip_distance_invoice_paid ====
CREATE OR REPLACE VIEW default.v_AU_c_trip_distance_invoice_paid (`month_year` Nullable(Date), `transaction_count` UInt64, `total_amount` Nullable(Float64), `total_fees` Nullable(Float64), `net_amount` Nullable(Float64)) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month_year, count(*) AS transaction_count, sum(bt.amount) / 100. AS total_amount, sum(bt.fee) / 100. AS total_fees, sum(bt.net) / 100. AS net_amount FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_charges AS c ON bt.source = c.id INNER JOIN default.au_stripe_invoices AS i ON c.invoice = i.id INNER JOIN default.au_stripe_invoices AS im_dist ON (i.id = im_dist.id) AND (JSONExtractString(im_dist.metadata, 'distanceTransactionId') != '') WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NOT NULL) AND ((i.subscription IS NULL) OR (i.subscription = '')) AND (lower(bt.description) NOT LIKE '%verifications charge%') AND (lower(bt.description) NOT LIKE '%security deposit%') AND (lower(bt.description) NOT LIKE '%refundable deposit%') GROUP BY toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) HAVING month_year < toStartOfMonth(today()) ORDER BY month_year DESC;

-- ==== v_AU_c_trip_refunds ====
CREATE OR REPLACE VIEW default.v_AU_c_trip_refunds (`month_year` Nullable(Date), `amount` Nullable(Float64), `total_fees` Nullable(Float64), `net_amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month_year, sum(bt.amount) / 100. AS amount, sum(bt.fee) / 100. AS total_fees, sum(bt.net) / 100. AS net_amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_refunds AS r ON bt.source = r.id INNER JOIN default.au_stripe_charges AS c ON r.charge = c.id INNER JOIN default.au_stripe_charges AS cm ON (c.id = cm.id) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') != '') LEFT JOIN default.au_stripe_refunds AS rm ON r.id = rm.id WHERE (1 = 1) AND (bt.reporting_category = 'refund') AND (bt.amount < 0) AND (lower(bt.description) NOT LIKE '%refundable deposit%') AND (lower(bt.description) NOT LIKE '%verifications charge%') AND ((JSONExtractString(rm.metadata, 'category') = '') OR (JSONExtractString(rm.metadata, 'category') != 'fuelrefund')) GROUP BY toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) HAVING month_year < toStartOfMonth(today()) ORDER BY month_year DESC;

-- ==== v_AU_c_verification_charge_received ====
CREATE OR REPLACE VIEW default.v_AU_c_verification_charge_received (`month` Nullable(Date), `transaction_count` UInt64, `amount` Nullable(Float64), `total_fees` Nullable(Float64), `net_amount` Nullable(Float64)) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month, count(*) AS transaction_count, sum(bt.amount) / 100. AS amount, sum(bt.fee) / 100. AS total_fees, sum(bt.net) / 100. AS net_amount FROM default.au_stripe_balance_transactions AS bt WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (bt.description LIKE '%Verifications Charge%') GROUP BY toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_AU_c_verification_refunds ====
CREATE OR REPLACE VIEW default.v_AU_c_verification_refunds (`month_year` Nullable(Date), `amount` Nullable(Float64), `total_fees` Nullable(Float64), `net_amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month_year, sum(bt.amount) / 100. AS amount, sum(bt.fee) / 100. AS total_fees, sum(bt.net) / 100. AS net_amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_refunds AS r ON bt.source = r.id INNER JOIN default.au_stripe_charges AS c ON r.charge = c.id INNER JOIN default.au_stripe_charges AS cm ON (c.id = cm.id) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') != '') LEFT JOIN default.au_stripe_refunds AS rm ON r.id = rm.id WHERE (1 = 1) AND (bt.reporting_category = 'refund') AND (bt.amount < 0) AND ((JSONExtractString(rm.metadata, 'category') = '') OR (JSONExtractString(rm.metadata, 'category') != 'fuelrefund')) AND (lower(bt.description) LIKE '%verifications charge%') GROUP BY toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) HAVING month_year < toStartOfMonth(today()) ORDER BY month_year DESC;

-- ==== v_SG_a_cost_fuel_net ====
CREATE OR REPLACE VIEW default.v_SG_a_cost_fuel_net (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType IN ('fuel_inclusion', 'fuel_charge', 'fuel_refund')) AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_cost_late_return ====
CREATE OR REPLACE VIEW default.v_SG_a_cost_late_return (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType IN ('late_return')) AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_host_delivery_payout ====
CREATE OR REPLACE VIEW default.v_SG_a_host_delivery_payout (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType = 'delivery') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_host_discounts ====
CREATE OR REPLACE VIEW default.v_SG_a_host_discounts (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType = 'long_term_discount') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_host_flexplus_payout ====
CREATE OR REPLACE VIEW default.v_SG_a_host_flexplus_payout (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType = 'flexplus') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_host_incidentals_cleanliness ====
CREATE OR REPLACE VIEW default.v_SG_a_host_incidentals_cleanliness (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType = 'cleanliness') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_host_incidentals_damage ====
CREATE OR REPLACE VIEW default.v_SG_a_host_incidentals_damage (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType = 'damage') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_host_incidentals_excess_mileage ====
CREATE OR REPLACE VIEW default.v_SG_a_host_incidentals_excess_mileage (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType = 'excess_mileage') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_host_incidentals_tolls ====
CREATE OR REPLACE VIEW default.v_SG_a_host_incidentals_tolls (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType = 'tolls') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_host_misc_charge_collected ====
CREATE OR REPLACE VIEW default.v_SG_a_host_misc_charge_collected (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType = 'misc_charge') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_host_payout_regular_p2p ====
CREATE OR REPLACE VIEW default.v_SG_a_host_payout_regular_p2p (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT multiIf((pe.tripId IS NOT NULL) AND (JSONExtractUInt(mt.protectedData, 'bookingDisplayEnd') > 0) AND match(toString(JSONExtractUInt(mt.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), toStartOfMonth(fromUnixTimestamp(toUInt32(JSONExtractUInt(mt.protectedData, 'bookingDisplayEnd') / 1000))), toStartOfMonth(pe.createdAt)) AS month, round(sum(pe.payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_payout_entries AS pe LEFT JOIN default.v_host_mechanism_map AS m ON (m.market = 'SG') AND (m.host_id = pe.hostId) LEFT JOIN default.sg_transactions AS mt ON pe.tripId = mt.id WHERE (pe.payoutType IN ('duration', 'distance', 'trip')) AND ((pe.finance_status IS NULL) OR (pe.finance_status != 'Under Review')) AND ((pe.tripStatus IS NULL) OR (pe.tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) AND (ifNull(m.mechanism, 'p2p') = 'p2p') GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_host_subscription_collected ====
CREATE OR REPLACE VIEW default.v_SG_a_host_subscription_collected (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType = 'subscription') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_host_superhost_payout ====
CREATE OR REPLACE VIEW default.v_SG_a_host_superhost_payout (`month` Nullable(Date), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `payout_count` UInt64, `days_with_payouts` UInt64) AS SELECT toStartOfMonth(bt.created) AS month, round(toFloat64(sum(bt.amount)) / 100., 2) AS amount, round(toFloat64(sum(bt.fee)) / 100., 2) AS fee, round(toFloat64(sum(bt.net)) / 100., 2) AS net_amount, count() AS payout_count, countDistinct(toDate(bt.created)) AS days_with_payouts FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_transfers AS t ON bt.source = t.id INNER JOIN default.sg_stripe_transfers AS tm ON t.id = tm.id LEFT JOIN default.sg_stripe_charges AS c ON t.source_transaction = c.id LEFT JOIN default.sg_stripe_charges AS cm ON c.id = cm.id WHERE (bt.reporting_category = 'transfer') AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') IS NULL) AND (JSONExtractString(tm.metadata, 'code') IN ('3')) GROUP BY toStartOfMonth(bt.created) HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_SG_a_host_trip_earnings_rms ====
CREATE OR REPLACE VIEW default.v_SG_a_host_trip_earnings_rms (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(amt), 2) AS amount, sum(rc) AS row_count FROM (SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, payoutAmount / 100. AS amt, 1 AS rc FROM default.sg_payout_entries WHERE (payoutType = 'rms') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) UNION ALL SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, payoutAmount / 100. AS amt, 1 AS rc FROM default.sg_payout_entries WHERE (payoutType = 'misc_payout') AND (positionCaseInsensitive(ifNull(description, ''), 'rms') > 0) AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')))) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_incidentals_classified ====
CREATE OR REPLACE VIEW default.v_SG_a_incidentals_classified (`month` Nullable(Date), `invoice_id` String, `descr` String, `amount` Float64, `account_code` String) AS WITH (SELECT groupArray(keyword) FROM (SELECT keyword, account_code FROM default.incidentals_desc_lookup ORDER BY priority ASC)) AS kw, (SELECT groupArray(account_code) FROM (SELECT keyword, account_code FROM default.incidentals_desc_lookup ORDER BY priority ASC)) AS ac SELECT toStartOfMonth(toDate(i.created)) AS month, i.id AS invoice_id, JSONExtractString(line, 'description') AS descr, toFloat64(JSONExtractInt(line, 'amount')) / 100. AS amount, if(arrayFirstIndex(x -> (position(lower(JSONExtractString(line, 'description')), x) > 0), kw) = 0, '4025', ac[arrayFirstIndex(x -> (position(lower(JSONExtractString(line, 'description')), x) > 0), kw)]) AS account_code FROM default.sg_stripe_invoices AS i ARRAY JOIN JSONExtractArrayRaw(JSONExtractString(assumeNotNull(i.lines), 'data')) AS line WHERE (i.subscription IS NULL) AND (i.status NOT IN ('void', 'draft'));

-- ==== v_SG_a_incidentals_cleaning_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_incidentals_cleaning_invoiced (`month` Nullable(Date), `amount` Float64, `row_count` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_incidentals_classified WHERE account_code = '4022' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_incidentals_damage_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_incidentals_damage_invoiced (`month` Nullable(Date), `amount` Float64, `row_count` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_incidentals_classified WHERE account_code = '4021' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_incidentals_excess_mileage_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_incidentals_excess_mileage_invoiced (`month` Nullable(Date), `amount` Float64, `row_count` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_incidentals_classified WHERE account_code = '4024' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_incidentals_fines_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_incidentals_fines_invoiced (`month` Nullable(Date), `amount` Float64, `row_count` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_incidentals_classified WHERE account_code = '4028' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_incidentals_flexplus_leak_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_incidentals_flexplus_leak_invoiced (`month` Nullable(Date), `amount` Float64, `row_count` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_incidentals_classified WHERE account_code = '_LEAK_FLEXPLUS' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_incidentals_fuel_charge_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_incidentals_fuel_charge_invoiced (`month` Nullable(Date), `amount` Float64, `row_count` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_incidentals_classified WHERE account_code = '4023' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_incidentals_insurance_leak_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_incidentals_insurance_leak_invoiced (`month` Nullable(Date), `amount` Float64, `row_count` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_incidentals_classified WHERE account_code = '_LEAK_INSURANCE' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_incidentals_late_return_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_incidentals_late_return_invoiced (`month` Nullable(Date), `amount` Float64, `row_count` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_incidentals_classified WHERE account_code = '4031' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_incidentals_other_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_incidentals_other_invoiced (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, sum(row_count) AS row_count FROM (SELECT month, amount AS amount, 1 AS row_count FROM default.v_SG_a_incidentals_classified WHERE account_code = '4025' UNION ALL SELECT toStartOfMonth(toDate(bt.created)) AS month, bt.amount / 100. AS amount, 1 AS row_count FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_charges AS c ON bt.source = c.id LEFT JOIN default.sg_stripe_charges AS cm ON c.id = cm.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = '') AND (bt.description NOT LIKE '%verification%') AND (bt.description NOT LIKE '%deposit%')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_incidentals_penalty_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_incidentals_penalty_invoiced (`month` Nullable(Date), `amount` Float64, `row_count` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_incidentals_classified WHERE account_code = '4027' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_incidentals_platform_fees_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_incidentals_platform_fees_invoiced (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(amt), 2) AS amount, sum(rc) AS row_count FROM (SELECT month, amount AS amt, 1 AS rc FROM default.v_SG_a_incidentals_classified WHERE account_code = '4026' UNION ALL SELECT toStartOfMonth(toDate(i.created)) AS month, (i.amount_due - i.subtotal) / 100. AS amt, 1 AS rc FROM default.sg_stripe_invoices AS i WHERE (i.subscription IS NULL) AND (i.status NOT IN ('void', 'draft')) AND (i.amount_due != i.subtotal)) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_incidentals_tolls_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_incidentals_tolls_invoiced (`month` Nullable(Date), `amount` Float64, `row_count` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_incidentals_classified WHERE account_code = '4020' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_incidentals_trip_to_base_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_incidentals_trip_to_base_invoiced (`month` Nullable(Date), `amount` Float64, `row_count` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_incidentals_classified WHERE account_code = '4000' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_misc_damage ====
CREATE OR REPLACE VIEW default.v_SG_a_misc_damage (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_misc_payout_classified WHERE account_code = '5021' GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_misc_downtime ====
CREATE OR REPLACE VIEW default.v_SG_a_misc_downtime (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_misc_payout_classified WHERE account_code = '5043' GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_misc_parking ====
CREATE OR REPLACE VIEW default.v_SG_a_misc_parking (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_misc_payout_classified WHERE account_code = '5060' GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_misc_payout_classified ====
CREATE OR REPLACE VIEW default.v_SG_a_misc_payout_classified (`month` Nullable(Date), `payoutAmount` Nullable(Int32), `account_code` String) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, payoutAmount, multiIf(positionCaseInsensitive(d, 'toll') > 0, '5020', positionCaseInsensitive(d, 'tow') > 0, '5033', (positionCaseInsensitive(d, 'afca') > 0) OR (positionCaseInsensitive(d, 'loss of use') > 0) OR (positionCaseInsensitive(d, 'damage') > 0) OR (positionCaseInsensitive(d, 'repair') > 0) OR (positionCaseInsensitive(d, 'storage') > 0) OR (positionCaseInsensitive(d, 'key ') > 0) OR (positionCaseInsensitive(d, 'key replace') > 0), '5021', positionCaseInsensitive(d, 'sticker') > 0, '5041', (positionCaseInsensitive(d, 'superhost') > 0) OR (positionCaseInsensitive(d, 'super host') > 0), '5040', positionCaseInsensitive(d, 'downtime') > 0, '5043', positionCaseInsensitive(d, 'parking') > 0, '5060', '5042') AS account_code FROM (SELECT payoutAmount, createdAt, lowerUTF8(trimBoth(ifNull(description, ''))) AS d FROM default.sg_payout_entries WHERE (payoutType = 'misc_payout') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND ((tripStatus IS NULL) OR (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))));

-- ==== v_SG_a_misc_residual ====
CREATE OR REPLACE VIEW default.v_SG_a_misc_residual (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_misc_payout_classified WHERE account_code = '5042' GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_misc_sticker ====
CREATE OR REPLACE VIEW default.v_SG_a_misc_sticker (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_misc_payout_classified WHERE account_code = '5041' GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_misc_superhost ====
CREATE OR REPLACE VIEW default.v_SG_a_misc_superhost (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_misc_payout_classified WHERE account_code = '5040' GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_misc_tolls ====
CREATE OR REPLACE VIEW default.v_SG_a_misc_tolls (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_misc_payout_classified WHERE account_code = '5020' GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_misc_towing ====
CREATE OR REPLACE VIEW default.v_SG_a_misc_towing (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_misc_payout_classified WHERE account_code = '5033' GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_a_subscription_device_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_subscription_device_invoiced (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toDate(i.created)) AS month, round(sum(i.total / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_stripe_invoices AS i WHERE (i.subscription IS NOT NULL) AND (i.status NOT IN ('void', 'draft')) AND ((NOT ((JSONExtractString(i.metadata, 'payment_plan') != '') OR (lower(i.lines) LIKE '%payment plan%'))) AND (NOT (lower(i.lines) LIKE '%flex+%')) AND (NOT (lower(i.lines) LIKE '%insur%')) AND ((lower(i.lines) LIKE '%mates%') OR (lower(i.lines) LIKE '%drive lah go%') OR (lower(i.lines) LIKE '%dl go%') OR (lower(i.lines) LIKE '%dlg%') OR (lower(i.lines) LIKE '%gps%') OR (lower(i.lines) LIKE '%lockbox%') OR (lower(i.lines) LIKE '%keyless%') OR (lower(i.lines) LIKE '%byod%'))) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_subscription_flexplus_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_subscription_flexplus_invoiced (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toDate(i.created)) AS month, round(sum(i.total / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_stripe_invoices AS i WHERE (i.subscription IS NOT NULL) AND (i.status NOT IN ('void', 'draft')) AND ((NOT ((JSONExtractString(i.metadata, 'payment_plan') != '') OR (lower(i.lines) LIKE '%payment plan%'))) AND (lower(i.lines) LIKE '%flex+%')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_subscription_insurance_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_subscription_insurance_invoiced (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toDate(i.created)) AS month, round(sum(i.total / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_stripe_invoices AS i WHERE (i.subscription IS NOT NULL) AND (i.status NOT IN ('void', 'draft')) AND ((NOT ((JSONExtractString(i.metadata, 'payment_plan') != '') OR (lower(i.lines) LIKE '%payment plan%'))) AND (NOT (lower(i.lines) LIKE '%flex+%')) AND (lower(i.lines) LIKE '%insur%')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_subscription_other_invoiced ====
CREATE OR REPLACE VIEW default.v_SG_a_subscription_other_invoiced (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toDate(i.created)) AS month, round(sum(i.total / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_stripe_invoices AS i WHERE (i.subscription IS NOT NULL) AND (i.status NOT IN ('void', 'draft')) AND ((NOT ((JSONExtractString(i.metadata, 'payment_plan') != '') OR (lower(i.lines) LIKE '%payment plan%'))) AND (NOT (lower(i.lines) LIKE '%flex+%')) AND (NOT (lower(i.lines) LIKE '%insur%')) AND (NOT ((lower(i.lines) LIKE '%mates%') OR (lower(i.lines) LIKE '%drive lah go%') OR (lower(i.lines) LIKE '%dl go%') OR (lower(i.lines) LIKE '%dlg%') OR (lower(i.lines) LIKE '%gps%') OR (lower(i.lines) LIKE '%lockbox%') OR (lower(i.lines) LIKE '%keyless%') OR (lower(i.lines) LIKE '%byod%')))) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_a_trip_revenue_p2p ====
CREATE OR REPLACE VIEW default.v_SG_a_trip_revenue_p2p (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(multiIf(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000) > 0, dateTrunc('month', fromUnixTimestamp(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000))), dateTrunc('month', toDateTime(bt.created)))) AS month, round(sum(bt.amount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_charges AS c ON bt.source = c.id INNER JOIN default.sg_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.sg_transactions AS txn ON JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = txn.id LEFT JOIN default.v_host_mechanism_map AS m ON (txn.providerId = m.host_id) AND (m.market = 'SG') WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') != '') AND (bt.description NOT LIKE '%deposit%') AND (bt.description NOT LIKE '%verification%') AND ((txn.processName IS NULL) OR (txn.processName != 'fuel-charging')) AND ((m.mechanism = 'p2p') OR (m.mechanism IS NULL)) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_SG_a_trip_revenue_rms ====
CREATE OR REPLACE VIEW default.v_SG_a_trip_revenue_rms (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(multiIf(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000) > 0, dateTrunc('month', fromUnixTimestamp(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000))), dateTrunc('month', toDateTime(bt.created)))) AS month, round(sum(bt.amount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_charges AS c ON bt.source = c.id INNER JOIN default.sg_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.sg_transactions AS txn ON JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = txn.id LEFT JOIN default.v_host_mechanism_map AS m ON (txn.providerId = m.host_id) AND (m.market = 'SG') WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') != '') AND (bt.description NOT LIKE '%deposit%') AND (bt.description NOT LIKE '%verification%') AND ((txn.processName IS NULL) OR (txn.processName != 'fuel-charging')) AND (m.mechanism = 'rms') GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_SG_c_customer_deposits_received ====
CREATE OR REPLACE VIEW default.v_SG_c_customer_deposits_received (`month` Nullable(Date), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `transaction_count` UInt64, `days_with_deposits` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(sum(bt.amount / 100.), 2) AS amount, round(sum(bt.fee / 100.), 2) AS fee, round(sum(bt.net / 100.), 2) AS net_amount, count(*) AS transaction_count, uniqExact(toDate(bt.created)) AS days_with_deposits FROM default.sg_stripe_balance_transactions AS bt WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND ((bt.description LIKE '%deposit%') OR (bt.description LIKE '%Admin Deposit Listing%')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_SG_c_deposit_internal_transfer ====
CREATE OR REPLACE VIEW default.v_SG_c_deposit_internal_transfer (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(-sum(bt.amount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_transfers AS t ON t.id = bt.source WHERE (bt.reporting_category IN ('transfer', 'transfer_reversal')) AND (t.destination = 'acct_1EhuMGAcVqeggTlg') GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_c_deposit_refunds ====
CREATE OR REPLACE VIEW default.v_SG_c_deposit_refunds (`month` Nullable(Date), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `transaction_count` UInt64, `days_with_refunds` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(sum(bt.amount / 100.), 2) AS amount, round(sum(bt.fee / 100.), 2) AS fee, round(sum(bt.net / 100.), 2) AS net_amount, count(*) AS transaction_count, uniqExact(toDate(bt.created)) AS days_with_refunds FROM default.sg_stripe_balance_transactions AS bt WHERE (bt.reporting_category = 'refund') AND (bt.amount < 0) AND (lower(bt.description) LIKE '%deposit%') GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_SG_c_disputes ====
CREATE OR REPLACE VIEW default.v_SG_c_disputes (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(-sum(bt.amount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_stripe_balance_transactions AS bt WHERE bt.reporting_category IN ('dispute', 'dispute_reversal') GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_c_host_rms_internal_clearing ====
CREATE OR REPLACE VIEW default.v_SG_c_host_rms_internal_clearing (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(-sum(bt.amount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_transfers AS t ON t.id = bt.source WHERE (bt.reporting_category IN ('transfer', 'transfer_reversal')) AND (t.destination IN (SELECT id FROM default.sg_stripe_connected_accounts WHERE match(email, 'rms[0-9]') OR (email ILIKE '%flexplus%') OR (email ILIKE '%caretaker%'))) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_c_host_transfers ====
CREATE OR REPLACE VIEW default.v_SG_c_host_transfers (`month` Nullable(Date), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `transfer_count` UInt64, `transfers` UInt64, `transfer_reversals` UInt64, `application_fees` UInt64, `application_fee_refunds` UInt64, `days_with_transfers` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(sum(bt.amount / 100.), 2) AS amount, round(sum(bt.fee / 100.), 2) AS fee, round(sum(bt.net / 100.), 2) AS net_amount, count(*) AS transfer_count, countIf(bt.reporting_category = 'transfer') AS transfers, countIf(bt.reporting_category = 'transfer_reversal') AS transfer_reversals, countIf(bt.reporting_category = 'platform_earning') AS application_fees, countIf(bt.reporting_category = 'platform_earning_refund') AS application_fee_refunds, uniqExact(toDate(bt.created)) AS days_with_transfers FROM default.sg_stripe_balance_transactions AS bt LEFT JOIN default.sg_stripe_transfers AS t ON t.id = bt.source WHERE (bt.reporting_category IN ('transfer', 'transfer_reversal', 'platform_earning', 'platform_earning_refund')) AND (NOT ((bt.reporting_category IN ('transfer', 'transfer_reversal')) AND ((t.destination IN (SELECT id FROM default.sg_stripe_connected_accounts WHERE match(email, 'rms[0-9]') OR (email ILIKE '%flexplus%') OR (email ILIKE '%caretaker%'))) OR (t.destination IN ('acct_1EhuMGAcVqeggTlg', 'acct_1JkKmQQWb9mOwfae'))))) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_SG_c_incidentals_invoice_paid ====
CREATE OR REPLACE VIEW default.v_SG_c_incidentals_invoice_paid (`month` Nullable(Date), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `transaction_count` UInt64, `unique_invoices` UInt64, `non_invoice_charges` UInt64, `invoice_charges` UInt64, `days_with_payments` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(sum(bt.amount / 100.), 2) AS amount, round(sum(bt.fee / 100.), 2) AS fee, round(sum(bt.net / 100.), 2) AS net_amount, count(*) AS transaction_count, uniqExactIf(c.invoice, c.invoice IS NOT NULL) AS unique_invoices, countIf(c.invoice IS NULL) AS non_invoice_charges, countIf(c.invoice IS NOT NULL) AS invoice_charges, uniqExact(toDate(bt.created)) AS days_with_payments FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_charges AS c ON bt.source = c.id LEFT JOIN default.sg_stripe_invoices AS i ON c.invoice = i.id LEFT JOIN default.sg_stripe_charges AS cm ON c.id = cm.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (bt.description NOT LIKE '%verification%') AND (bt.description NOT LIKE '%deposit%') AND (((c.invoice IS NOT NULL) AND (i.subscription IS NULL)) OR ((c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = ''))) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_SG_c_invoice_payment_refunds ====
CREATE OR REPLACE VIEW default.v_SG_c_invoice_payment_refunds (`month` Nullable(Date), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `transaction_count` UInt64, `unique_invoices_refunded` UInt64, `days_with_refunds` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(sum(bt.amount / 100.), 2) AS amount, round(sum(bt.fee / 100.), 2) AS fee, round(sum(bt.net / 100.), 2) AS net_amount, count(*) AS transaction_count, uniqExact(c.invoice) AS unique_invoices_refunded, uniqExact(toDate(bt.created)) AS days_with_refunds FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_refunds AS r ON bt.source = r.id INNER JOIN default.sg_stripe_charges AS c ON r.charge = c.id LEFT JOIN default.sg_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.sg_stripe_invoices AS i ON c.invoice = i.id WHERE (bt.reporting_category = 'refund') AND (bt.amount < 0) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = '') AND ((c.invoice IS NULL) OR (i.subscription IS NULL)) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_SG_c_stripe_fees_paid ====
CREATE OR REPLACE VIEW default.v_SG_c_stripe_fees_paid (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toDate(created)) AS month, round((sum(if(reporting_category != 'connect_reserved_funds', fee, 0)) + sum(if(reporting_category = 'fee', abs(amount), 0))) / 100., 2) AS amount, count(*) AS row_count FROM default.sg_stripe_balance_transactions GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_c_stripe_payouts ====
CREATE OR REPLACE VIEW default.v_SG_c_stripe_payouts (`transaction_date` Nullable(DateTime('Asia/Singapore')), `balance_transaction_id` String, `payout_date` Nullable(DateTime), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `description` Nullable(String), `status` Nullable(String)) AS SELECT toTimeZone(toDateTime(bt.created), 'Asia/Singapore') AS transaction_date, bt.id AS balance_transaction_id, bt.created AS payout_date, round(bt.amount / 100., 2) AS amount, round(bt.fee / 100., 2) AS fee, round(bt.net / 100., 2) AS net_amount, bt.description, bt.status FROM default.sg_stripe_balance_transactions AS bt WHERE ((bt.type = 'payout') OR (bt.type = 'payout_cancel')) AND (bt.status = 'available') ORDER BY bt.created DESC;

-- ==== v_SG_c_stripe_platform_adjustments ====
CREATE OR REPLACE VIEW default.v_SG_c_stripe_platform_adjustments (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(created, 'UTC')) AS month, round(-sum(amount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_stripe_balance_transactions WHERE reporting_category IN ('refund_failure', 'connect_collection_transfer', 'charge_failure') GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== v_SG_c_stripe_reserve ====
CREATE OR REPLACE VIEW default.v_SG_c_stripe_reserve (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(created) AS month, round(-sum(amount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_stripe_balance_transactions WHERE reporting_category = 'connect_reserved_funds' GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== v_SG_c_subscription_invoice_paid ====
CREATE OR REPLACE VIEW default.v_SG_c_subscription_invoice_paid (`month` Nullable(Date), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `transaction_count` UInt64, `unique_invoices` UInt64, `unique_subscriptions` UInt64, `days_with_payments` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(sum(bt.amount / 100.), 2) AS amount, round(sum(bt.fee / 100.), 2) AS fee, round(sum(bt.net / 100.), 2) AS net_amount, count(*) AS transaction_count, uniqExact(c.invoice) AS unique_invoices, uniqExact(i.subscription) AS unique_subscriptions, uniqExact(toDate(bt.created)) AS days_with_payments FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_charges AS c ON bt.source = c.id INNER JOIN default.sg_stripe_invoices AS i ON c.invoice = i.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NOT NULL) AND (i.subscription IS NOT NULL) AND (bt.description NOT LIKE '%verification%') AND (bt.description NOT LIKE '%deposit%') GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_SG_c_subscription_refunds_device ====
CREATE OR REPLACE VIEW default.v_SG_c_subscription_refunds_device (`month` Nullable(Date), `amount` Nullable(Float64), `transaction_count` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(sum(bt.amount / 100.), 2) AS amount, count(*) AS transaction_count FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_refunds AS r ON bt.source = r.id INNER JOIN default.sg_stripe_charges AS c ON r.charge = c.id LEFT JOIN default.sg_stripe_invoices AS i ON c.invoice = i.id LEFT JOIN default.sg_stripe_charges AS cm ON c.id = cm.id WHERE (bt.reporting_category = 'refund') AND (bt.amount < 0) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = '') AND (c.invoice IS NOT NULL) AND (i.subscription IS NOT NULL) AND (NOT (lower(coalesce(i.lines, '')) LIKE '%insur%')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_SG_c_subscription_refunds_insurance ====
CREATE OR REPLACE VIEW default.v_SG_c_subscription_refunds_insurance (`month` Nullable(Date), `amount` Nullable(Float64), `transaction_count` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(sum(bt.amount / 100.), 2) AS amount, count(*) AS transaction_count FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_refunds AS r ON bt.source = r.id INNER JOIN default.sg_stripe_charges AS c ON r.charge = c.id LEFT JOIN default.sg_stripe_invoices AS i ON c.invoice = i.id LEFT JOIN default.sg_stripe_charges AS cm ON c.id = cm.id WHERE (bt.reporting_category = 'refund') AND (bt.amount < 0) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = '') AND (c.invoice IS NOT NULL) AND (i.subscription IS NOT NULL) AND (lower(i.lines) LIKE '%insur%') GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_SG_c_trip_cash_collected ====
CREATE OR REPLACE VIEW default.v_SG_c_trip_cash_collected (`month` Nullable(Date), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `transaction_count` UInt64, `unique_trips` UInt64, `days_with_trips` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(sum(bt.amount / 100.), 2) AS amount, round(sum(bt.fee / 100.), 2) AS fee, round(sum(bt.net / 100.), 2) AS net_amount, count(*) AS transaction_count, uniqExact(JSONExtractString(cm.metadata, 'sharetribe-transaction-id')) AS unique_trips, uniqExact(toDate(bt.created)) AS days_with_trips FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_charges AS c ON bt.source = c.id INNER JOIN default.sg_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.sg_transactions AS txn ON JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = txn.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') != '') AND (coalesce(lower(bt.description), '') NOT LIKE '%deposit%') AND (coalesce(lower(bt.description), '') NOT LIKE '%verification%') AND ((txn.processName IS NULL) OR (txn.processName != 'fuel-charging')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_SG_c_trip_fuel_cash_collected ====
CREATE OR REPLACE VIEW default.v_SG_c_trip_fuel_cash_collected (`month` Nullable(Date), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `transaction_count` UInt64, `unique_trips` UInt64, `days_with_trips` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(sum(bt.amount / 100.), 2) AS amount, round(sum(bt.fee / 100.), 2) AS fee, round(sum(bt.net / 100.), 2) AS net_amount, count(*) AS transaction_count, uniqExact(JSONExtractString(cm.metadata, 'sharetribe-transaction-id')) AS unique_trips, uniqExact(toDate(bt.created)) AS days_with_trips FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_charges AS c ON bt.source = c.id INNER JOIN default.sg_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.sg_transactions AS txn ON JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = txn.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') != '') AND (bt.description NOT LIKE '%deposit%') AND (txn.processName = 'fuel-charging') GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_SG_c_trip_refunds ====
CREATE OR REPLACE VIEW default.v_SG_c_trip_refunds (`month` Nullable(Date), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `transaction_count` UInt64, `unique_trips_refunded` UInt64, `days_with_refunds` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(sum(bt.amount / 100.), 2) AS amount, round(sum(bt.fee / 100.), 2) AS fee, round(sum(bt.net / 100.), 2) AS net_amount, count(*) AS transaction_count, uniqExact(JSONExtractString(cm.metadata, 'sharetribe-transaction-id')) AS unique_trips_refunded, uniqExact(toDate(bt.created)) AS days_with_refunds FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_refunds AS r ON bt.source = r.id INNER JOIN default.sg_stripe_charges AS c ON r.charge = c.id INNER JOIN default.sg_stripe_charges AS cm ON c.id = cm.id WHERE (bt.reporting_category = 'refund') AND (bt.amount < 0) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') != '') AND (lower(bt.description) NOT LIKE '%deposit%') GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== v_host_mechanism_map ====
CREATE OR REPLACE VIEW default.v_host_mechanism_map (`market` String, `host_id` Nullable(String), `mechanism` String) AS SELECT 'SG' AS market, uid AS host_id, multiIf(max(is_rms) = 1, 'rms', 'p2p') AS mechanism FROM (SELECT JSONExtractString(metadata, 'sharetribe-user-id') AS uid, toUInt8((email LIKE '%flexplus%') OR (email LIKE '%caretaker%') OR match(email, 'rms[0-9]')) AS is_rms FROM default.sg_stripe_connected_accounts WHERE JSONExtractString(metadata, 'sharetribe-user-id') != '') GROUP BY uid UNION ALL SELECT 'AU' AS market, uid AS host_id, multiIf(max(is_rms) = 1, 'rms', 'p2p') AS mechanism FROM (SELECT JSONExtractString(metadata, 'sharetribe-user-id') AS uid, toUInt8((email LIKE '%flexplus%') OR (email LIKE '%caretaker%') OR match(email, 'rms[0-9]')) AS is_rms FROM default.au_stripe_connected_accounts WHERE JSONExtractString(metadata, 'sharetribe-user-id') != '') GROUP BY uid;

-- ==== view_AU_a_cost_discounts ====
CREATE OR REPLACE VIEW default.view_AU_a_cost_discounts (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType IN ('promo_discount', 'long_term_discount')) AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== view_AU_a_host_fuel_charge_collected ====
CREATE OR REPLACE VIEW default.view_AU_a_host_fuel_charge_collected (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType IN ('fuel_charge', 'fuel_refund')) AND (payoutAmount < 0) AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) HAVING month < toStartOfMonth(today());

-- ==== view_AU_a_host_incidentals_fuel ====
CREATE OR REPLACE VIEW default.view_AU_a_host_incidentals_fuel (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, sum(payoutAmount) / 100. AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType IN ('fuel_charge', 'fuel_refund')) AND (payoutAmount > 0) AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) HAVING month < toStartOfMonth(today());

-- ==== view_AU_a_host_misc_payout ====
CREATE OR REPLACE VIEW default.view_AU_a_host_misc_payout (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) AS month, sum(payoutAmount) / 100. AS amount, count(*) AS row_count FROM default.au_payout_entries WHERE (payoutType = 'misc_payout') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Australia/Sydney')) HAVING month < toStartOfMonth(today());

-- ==== view_AU_a_host_payout_flexplus_p2p ====
CREATE OR REPLACE VIEW default.view_AU_a_host_payout_flexplus_p2p (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(pe.createdAt, 'Australia/Sydney')) AS month, round(sum(pe.payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_payout_entries AS pe LEFT JOIN default.v_host_mechanism_map AS m ON (m.market = 'AU') AND (m.host_id = pe.hostId) WHERE (pe.payoutType = 'flexplus') AND ((pe.finance_status IS NULL) OR (pe.finance_status != 'Under Review')) AND (pe.tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) AND (ifNull(m.mechanism, 'p2p') = 'p2p') GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== view_AU_a_host_payout_flexplus_rms ====
CREATE OR REPLACE VIEW default.view_AU_a_host_payout_flexplus_rms (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(pe.createdAt, 'Australia/Sydney')) AS month, round(sum(pe.payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_payout_entries AS pe LEFT JOIN default.v_host_mechanism_map AS m ON (m.market = 'AU') AND (m.host_id = pe.hostId) WHERE (pe.payoutType = 'flexplus') AND ((pe.finance_status IS NULL) OR (pe.finance_status != 'Under Review')) AND (pe.tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) AND (ifNull(m.mechanism, 'p2p') = 'rms') GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== view_AU_a_host_payout_regular_rms ====
CREATE OR REPLACE VIEW default.view_AU_a_host_payout_regular_rms (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(pe.createdAt, 'Australia/Sydney')) AS month, round(sum(pe.payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.au_payout_entries AS pe LEFT JOIN default.v_host_mechanism_map AS m ON (m.market = 'AU') AND (m.host_id = pe.hostId) WHERE ((pe.finance_status IS NULL) OR (pe.finance_status != 'Under Review')) AND (pe.tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) AND (((pe.payoutType IN ('duration', 'distance', 'trip')) AND (ifNull(m.mechanism, 'p2p') = 'rms')) OR (pe.payoutType = 'rms')) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== view_AU_a_host_trip_earnings_accrual ====
CREATE OR REPLACE VIEW default.view_AU_a_host_trip_earnings_accrual (`month` Nullable(Date), `total_host_trip_earnings` Nullable(Float64), `payout_count` UInt64, `unique_hosts` UInt64, `unique_trips` UInt64, `duration_earnings` Nullable(Float64), `distance_earnings` Nullable(Float64), `late_return_earnings` Nullable(Float64), `duration_count` UInt64, `distance_count` UInt64, `late_return_count` UInt64) AS WITH trip_payouts AS (SELECT pe.id, pe.payoutType, pe.payoutAmount, pe.tripId, pe.hostId, pe.createdAt AS payout_created_at, multiIf((pe.tripId IS NOT NULL) AND (JSONExtractUInt(mt.protectedData, 'bookingDisplayEnd') > 0) AND match(toString(JSONExtractUInt(mt.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), toStartOfMonth(fromUnixTimestamp(toUInt32(JSONExtractUInt(mt.protectedData, 'bookingDisplayEnd') / 1000))), toStartOfMonth(pe.createdAt)) AS accrual_month FROM default.au_payout_entries AS pe LEFT JOIN default.au_transactions AS mt ON pe.tripId = mt.id WHERE (pe.payoutType IN ('duration', 'distance', 'late_return', 'trip')) AND ((pe.finance_status != 'Under Review') OR (pe.finance_status IS NULL)) AND (pe.tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) SELECT accrual_month AS month, sum(payoutAmount / 100.) AS total_host_trip_earnings, count(*) AS payout_count, COUNTDistinct(hostId) AS unique_hosts, COUNTDistinct(tripId) AS unique_trips, sum(if(payoutType = 'duration', payoutAmount / 100., 0)) AS duration_earnings, sum(if(payoutType = 'distance', payoutAmount / 100., 0)) AS distance_earnings, sum(if(payoutType = 'late_return', payoutAmount / 100., 0)) AS late_return_earnings, countIf(payoutType = 'duration') AS duration_count, countIf(payoutType = 'distance') AS distance_count, countIf(payoutType = 'late_return') AS late_return_count FROM trip_payouts WHERE accrual_month IS NOT NULL GROUP BY accrual_month HAVING month < toStartOfMonth(today()) ORDER BY accrual_month DESC;

-- ==== view_AU_a_incidentals_direct_revenue ====
CREATE OR REPLACE VIEW default.view_AU_a_incidentals_direct_revenue (`month` Nullable(Date), `amount` Nullable(Float64), `charge_count` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(sum(bt.amount) / 100., 2) AS amount, count(*) AS charge_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_charges AS c ON bt.source = c.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== view_AU_a_incidentals_direct_revenue_new ====
CREATE OR REPLACE VIEW default.view_AU_a_incidentals_direct_revenue_new (`month` Nullable(Date), `amount` Nullable(Float64), `charge_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month, round(sum(bt.amount) / 100., 2) AS amount, count(*) AS charge_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_charges AS c ON bt.source = c.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== view_AU_a_incidentals_invoiced ====
CREATE OR REPLACE VIEW default.view_AU_a_incidentals_invoiced (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimezone(i.created, 'Australia/Sydney')) AS month, sum(i.amount_due) / 100. AS amount, count(*) AS row_count FROM default.au_stripe_invoices AS i LEFT JOIN default.au_stripe_invoices AS im ON i.id = im.id WHERE (i.subscription IS NULL) AND ((JSONExtractString(im.metadata, 'distanceTransactionId') IS NULL) OR (JSONExtractString(im.metadata, 'distanceTransactionId') = '')) AND (i.status NOT IN ('void', 'draft')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== view_AU_a_misc_ ====
CREATE OR REPLACE VIEW default.view_AU_a_misc_ (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.v_AU_a_misc_payout_classified WHERE account_code = '5001C corrections_rms_clearing' GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== view_AU_a_subscription_invoiced ====
CREATE OR REPLACE VIEW default.view_AU_a_subscription_invoiced (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimezone(i.created, 'Australia/Sydney')) AS month, sum(i.amount_due) / 100. AS amount, count(*) AS row_count FROM default.au_stripe_invoices AS i WHERE (i.subscription IS NOT NULL) AND (i.status NOT IN ('void', 'draft')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== view_AU_a_subscription_payment_plan ====
CREATE OR REPLACE VIEW default.view_AU_a_subscription_payment_plan (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimezone(i.created, 'Australia/Sydney')) AS month, sum(i.amount_due) / 100. AS amount, count(*) AS row_count FROM default.au_stripe_invoices AS i WHERE (i.subscription IS NOT NULL) AND (i.status NOT IN ('void', 'draft')) AND ((JSONExtractString(i.metadata, 'payment_plan') != '') OR (lower(i.lines) LIKE '%payment plan%')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== view_AU_a_trip_revenue_earned ====
CREATE OR REPLACE VIEW default.view_AU_a_trip_revenue_earned (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimezone(multiIf((JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') > 0) AND match(toString(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), fromUnixTimestamp(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000)), ((JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') IS NULL) OR (JSONExtractString(txn.protectedData, 'bookingDisplayEnd') = 'NaN')) AND (JSONExtractString(txn.protectedData, 'parentTxId') IS NOT NULL) AND (JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') IS NOT NULL) AND match(toString(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), fromUnixTimestamp(toUInt32(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') / 1000)), bt.created), 'Australia/Sydney')) AS month, sum(bt.amount) / 100. AS amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_charges AS c ON bt.source = c.id LEFT JOIN default.au_stripe_charges AS cm ON c.id = cm.id INNER JOIN default.au_transactions AS txn ON JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = txn.id LEFT JOIN default.au_transactions AS parent_txn ON JSONExtractString(txn.protectedData, 'parentTxId') = parent_txn.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') IS NOT NULL) AND (txn.processName NOT IN ('distance-charging', 'unpaid-dues')) AND (bt.description NOT ILIKE '%Verifications Charge%') AND (bt.description NOT ILIKE '%Security deposit%') AND (bt.description NOT ILIKE '%Refundable Deposit%') AND (((JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') IS NOT NULL) AND match(toString(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$')) OR ((JSONExtractString(txn.protectedData, 'parentTxId') IS NOT NULL) AND (JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') IS NOT NULL) AND match(toString(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$')) OR (bt.created IS NOT NULL)) GROUP BY month HAVING month < toStartOfMonth(now()) ORDER BY month DESC;

-- ==== view_AU_c_connect_balance_recon ====
CREATE OR REPLACE VIEW default.view_AU_c_connect_balance_recon (`month` Nullable(Date), `charges_net` Nullable(Float64), `payouts_net` Nullable(Float64), `refunds_net` Nullable(Float64), `fees_net` Nullable(Float64), `adjustments_net` Nullable(Float64), `net_flow` Nullable(Float64), `txn_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(created, 'Australia/Sydney')) AS month, round(sumIf(net / 100., reporting_category = 'charge'), 2) AS charges_net, round(sumIf(net / 100., reporting_category IN ('payout', 'payout_reversal')), 2) AS payouts_net, round(sumIf(net / 100., reporting_category = 'refund'), 2) AS refunds_net, round(sumIf(net / 100., reporting_category = 'fee'), 2) AS fees_net, round(sumIf(net / 100., reporting_category NOT IN ('charge', 'payout', 'payout_reversal', 'refund', 'fee')), 2) AS adjustments_net, round(sum(net / 100.), 2) AS net_flow, count(*) AS txn_count FROM default.au_stripe_balance_transactions_for_connected_accounts GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== view_AU_c_subscription_refunds ====
CREATE OR REPLACE VIEW default.view_AU_c_subscription_refunds (`month_year` Nullable(Date), `amount` Nullable(Float64), `total_fees` Nullable(Float64), `net_amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) AS month_year, sum(bt.amount) / 100. AS amount, sum(bt.fee) / 100. AS total_fees, sum(bt.net) / 100. AS net_amount, count(*) AS row_count FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_refunds AS r ON bt.source = r.id INNER JOIN default.au_stripe_charges AS c ON r.charge = c.id LEFT JOIN default.au_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.au_stripe_refunds AS rm ON r.id = rm.id WHERE (1 = 1) AND (bt.reporting_category = 'refund') AND (bt.amount < 0) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = '') AND ((JSONExtractString(rm.metadata, 'category') = '') OR (JSONExtractString(rm.metadata, 'category') != 'fuelrefund')) AND (lower(bt.description) NOT LIKE '%invoice%') AND (lower(bt.description) NOT LIKE '%payment%') GROUP BY toStartOfMonth(toTimeZone(bt.created, 'Australia/Sydney')) HAVING month_year < toStartOfMonth(today()) ORDER BY month_year DESC;

-- ==== view_AU_intermediate_payout_transactions ====
CREATE OR REPLACE VIEW default.view_AU_intermediate_payout_transactions (`payout_entry_id` Int32, `payout_tripId` Nullable(String), `payoutType` Nullable(String), `payoutAmount` Nullable(Int32), `payout_created_at` Nullable(DateTime), `finance_status` Nullable(String), `transaction_id` String, `booking_display_end` Nullable(DateTime), `parent_tx_id` Nullable(String), `parent_transaction_id` String, `parent_booking_display_end` Nullable(DateTime), `calculated_booking_end_date` Nullable(DateTime), `calculated_parent_booking_end_date` Nullable(DateTime), `final_accrual_date` Nullable(DateTime), `date_source` String) AS SELECT pe.id AS payout_entry_id, pe.tripId AS payout_tripId, pe.payoutType, pe.payoutAmount, pe.createdAt AS payout_created_at, pe.finance_status, txn.id AS transaction_id, fromUnixTimestamp(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000)) AS booking_display_end, JSONExtractString(txn.protectedData, 'parentTxId') AS parent_tx_id, parent_txn.id AS parent_transaction_id, fromUnixTimestamp(toUInt32(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') / 1000)) AS parent_booking_display_end, multiIf((toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000) > 0) AND match(toString(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), fromUnixTimestamp(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000)), NULL) AS calculated_booking_end_date, multiIf((toUInt32(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') / 1000) > 0) AND match(toString(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), fromUnixTimestamp(toUInt32(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') / 1000)), NULL) AS calculated_parent_booking_end_date, multiIf((toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000) > 0) AND match(toString(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), fromUnixTimestamp(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000)), ((toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000) = 0) OR (toString(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd')) = 'NaN')) AND (JSONExtractString(txn.protectedData, 'parentTxId') != '') AND (toUInt32(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') / 1000) > 0) AND match(toString(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), fromUnixTimestamp(toUInt32(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') / 1000)), pe.createdAt) AS final_accrual_date, multiIf((toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000) > 0) AND match(toString(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), 'booking_display_end', ((toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000) = 0) OR (toString(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd')) = 'NaN')) AND (JSONExtractString(txn.protectedData, 'parentTxId') != '') AND (toUInt32(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd') / 1000) > 0) AND match(toString(JSONExtractUInt(parent_txn.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), 'parent_booking_display_end', 'payout_created_at') AS date_source FROM default.au_payout_entries AS pe LEFT JOIN default.au_transactions AS txn ON pe.tripId = txn.id LEFT JOIN default.au_transactions AS parent_txn ON JSONExtractString(txn.protectedData, 'parentTxId') = parent_txn.id WHERE (pe.payoutType IN ('duration', 'distance', 'late_return')) AND ((pe.finance_status IS NULL) OR (pe.finance_status != 'Under Review')) ORDER BY pe.createdAt DESC;

-- ==== view_AU_transactions_flat ====
CREATE OR REPLACE VIEW default.view_AU_transactions_flat (`createdAt` Nullable(DateTime), `processName` Nullable(String), `processVersion` Nullable(Int32), `payin_amount` Nullable(Int32), `payin_currency` Nullable(String), `payout_amount` Nullable(Int32), `payout_currency` Nullable(String), `lastTransition` Nullable(String), `lastTransitionedAt` Nullable(DateTime), `lineItems` String, `protectedData` Nullable(String), `metadata` Nullable(String), `transitions` Nullable(String), `id` String, `bookingStart` Nullable(DateTime), `bookingEnd` Nullable(DateTime), `listingId` Nullable(String), `providerId` Nullable(String), `customerId` Nullable(String), `providerResponded` UInt8, `successfullyCompleted` UInt8, `sequenceId` Int32, `dl_last_updated_at` DateTime, `transactionTimezone` Nullable(String), `bookingDisplayStart_utc` Nullable(DateTime), `bookingDisplayEnd_utc` Nullable(DateTime), `dropoffSentAt_utc` Nullable(DateTime), `tripReferenceCode` Nullable(String), `tripdays_calculated` Nullable(Float64), `actual_duration_hours` Nullable(Int64), `sch_duration_days` Nullable(Float64), `tripType` String, `distance_km_per_day` Nullable(Float64), `distanceTravelled_km` Nullable(Float64), `distanceHostPayout` Nullable(Float64), `distance_km` Nullable(Float64), `final_distance_km` Nullable(Float64), `distanceCharge_invoice` Nullable(String), `distanceCharge_paid` Nullable(String), `lateReturnHostPayout` Nullable(Float64), `lateReturnDuration` Nullable(Float64), `Child_distance_Charging_ID` Nullable(String), `childDistanceTransaction_childtxn` Nullable(String), `childDistanceTransaction_successful` Nullable(String), `first_successful_trip_of_user` Nullable(String)) AS WITH first_bookings AS (SELECT t.customerId, min(coalesce(parseDateTimeBestEffortOrNull(JSONExtractString(metadata, 'dropoffSentAt')), fromUnixTimestamp(toUInt32(JSONExtractUInt(protectedData, 'bookingDisplayEnd') / 1000)))) AS first_booking_date FROM default.au_transactions AS t INNER JOIN default.au_transactionmeanings AS tm ON t.lastTransition = tm.lastTransition WHERE (tm.Successfultrips = 1) AND (t.processName = 'one-for-all') GROUP BY t.customerId) SELECT t.*, JSONExtractString(t.protectedData, 'transactionTimezone') AS transactionTimezone, fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayStart') / 1000)) AS bookingDisplayStart_utc, fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayEnd') / 1000)) AS bookingDisplayEnd_utc, parseDateTimeBestEffortOrNull(JSONExtractString(t.metadata, 'dropoffSentAt')) AS dropoffSentAt_utc, JSONExtractString(metadata, 'tripReferenceCode') AS tripReferenceCode, multiIf(JSONExtractString(t.metadata, 'dropoffSentAt') != '', round(dateDiff('hour', fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayStart') / 1000)), parseDateTimeBestEffortOrNull(JSONExtractString(t.metadata, 'dropoffSentAt'))), 2) / 24, round(dateDiff('hour', fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayStart') / 1000)), fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayEnd') / 1000))), 2) / 24) AS tripdays_calculated, multiIf(JSONExtractString(t.metadata, 'dropoffSentAt') != '', round(dateDiff('hour', fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayStart') / 1000)), parseDateTimeBestEffortOrNull(JSONExtractString(t.metadata, 'dropoffSentAt'))), 2), round(dateDiff('hour', fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayStart') / 1000)), fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayEnd') / 1000))), 2)) AS actual_duration_hours, round(dateDiff('hour', fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayStart') / 1000)), fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayEnd') / 1000))), 2) / 24 AS sch_duration_days, multiIf(dateDiff('hour', fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayStart') / 1000)), fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayEnd') / 1000))) <= 6, 'hourly', dateDiff('hour', fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayStart') / 1000)), fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayEnd') / 1000))) > 6, 'daily', 'other') AS tripType, coalesce(JSONExtractFloat(t.metadata, 'distanceTravelled') / 1000, JSONExtractFloat(t.metadata, 'distanceCharge', 'distance') / 1000) / nullIf(multiIf(JSONExtractString(t.metadata, 'dropoffSentAt') != '', round(dateDiff('hour', fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayStart') / 1000)), parseDateTimeBestEffortOrNull(JSONExtractString(t.metadata, 'dropoffSentAt'))), 2) / 24, round(dateDiff('hour', fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayStart') / 1000)), fromUnixTimestamp(toUInt32(JSONExtractUInt(t.protectedData, 'bookingDisplayEnd') / 1000))), 2) / 24), 0) AS distance_km_per_day, JSONExtractFloat(t.metadata, 'distanceTravelled') / 1000 AS distanceTravelled_km, JSONExtractFloat(t.metadata, 'distanceCharge', 'distanceHostPayout') AS distanceHostPayout, JSONExtractFloat(t.metadata, 'distanceCharge', 'distance') / 1000 AS distance_km, coalesce(JSONExtractFloat(t.metadata, 'distanceTravelled') / 1000, JSONExtractFloat(t.metadata, 'distanceCharge', 'distance') / 1000) AS final_distance_km, JSONExtractString(t.metadata, 'distanceCharge', 'invoice') AS distanceCharge_invoice, JSONExtractString(t.metadata, 'distanceCharge', 'paid') AS distanceCharge_paid, JSONExtractFloat(t.metadata, 'lateReturn', 'lateReturnHostPayout') AS lateReturnHostPayout, JSONExtractFloat(t.metadata, 'lateReturn', 'lateReturnDuration') AS lateReturnDuration, JSONExtractString(t.metadata, 'distanceChargingId') AS Child_distance_Charging_ID, JSONExtractString(t.metadata, 'childDistanceTransaction', 'childtxn') AS childDistanceTransaction_childtxn, JSONExtractString(t.metadata, 'childDistanceTransaction', 'successful') AS childDistanceTransaction_successful, multiIf(fb.customerId IS NOT NULL, 'first_trip', NULL) AS first_successful_trip_of_user FROM default.au_transactions AS t LEFT JOIN first_bookings AS fb ON t.customerId = fb.customerId;

-- ==== view_AU_v_stripe_with_transaction_details ====
CREATE OR REPLACE VIEW default.view_AU_v_stripe_with_transaction_details (`payment_date` Nullable(DateTime), `payment_month` Nullable(Date), `payment_amount_usd` Nullable(Float64), `stripe_fee_usd` Nullable(Float64), `net_amount_usd` Nullable(Float64), `stripe_description` Nullable(String), `reporting_category` Nullable(String), `sharetribe_transaction_id` Nullable(String), `mysql_transaction_id` String, `transaction_created` Nullable(DateTime), `payin_amount_dollars` Nullable(Int32), `payout_amount_dollars` Nullable(Int32), `transaction_state` Nullable(String), `processName` Nullable(String), `booking_display_start` Nullable(DateTime), `booking_display_end` Nullable(DateTime), `parent_transaction_id` Nullable(String), `listingId` Nullable(String), `host_id` Nullable(String), `guest_id` Nullable(String)) AS SELECT bt.created AS payment_date, toStartOfMonth(bt.created) AS payment_month, toFloat64(bt.amount) / 100. AS payment_amount_usd, toFloat64(bt.fee) / 100. AS stripe_fee_usd, toFloat64(bt.net) / 100. AS net_amount_usd, bt.description AS stripe_description, bt.reporting_category, JSONExtractString(cm.metadata, 'sharetribe-transaction-id') AS sharetribe_transaction_id, txn.id AS mysql_transaction_id, txn.createdAt AS transaction_created, txn.payin_amount AS payin_amount_dollars, txn.payout_amount AS payout_amount_dollars, txn.lastTransition AS transaction_state, txn.processName, fromUnixTimestamp(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayStart') / 1000)) AS booking_display_start, fromUnixTimestamp(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000)) AS booking_display_end, JSONExtractString(txn.protectedData, 'parentTxId') AS parent_transaction_id, txn.listingId, txn.providerId AS host_id, txn.customerId AS guest_id FROM default.au_stripe_balance_transactions AS bt INNER JOIN default.au_stripe_charges AS c ON bt.source = c.id INNER JOIN default.au_stripe_charges AS cm ON cm.id = c.id INNER JOIN default.au_transactions AS txn ON txn.id = JSONExtractString(cm.metadata, 'sharetribe-transaction-id') WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') != '');

-- ==== view_SG_a_cost_discounts ====
CREATE OR REPLACE VIEW default.view_SG_a_cost_discounts (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType IN ('promo_discount', 'long_term_discount')) AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== view_SG_a_host_fuel_charge_collected_new ====
CREATE OR REPLACE VIEW default.view_SG_a_host_fuel_charge_collected_new (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType IN ('fuel_charge', 'fuel_refund')) AND (payoutAmount < 0) AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== view_SG_a_host_fuel_inclusion_new ====
CREATE OR REPLACE VIEW default.view_SG_a_host_fuel_inclusion_new (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType = 'fuel_inclusion') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== view_SG_a_host_incidentals_fuel_new ====
CREATE OR REPLACE VIEW default.view_SG_a_host_incidentals_fuel_new (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType IN ('fuel_charge', 'fuel_refund')) AND (payoutAmount > 0) AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== view_SG_a_host_long_term_discount_new ====
CREATE OR REPLACE VIEW default.view_SG_a_host_long_term_discount_new (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(payoutAmount) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType = 'long_term_discount') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== view_SG_a_host_misc_payout_new ====
CREATE OR REPLACE VIEW default.view_SG_a_host_misc_payout_new (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType = 'misc_payout') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== view_SG_a_host_payout_flexplus_p2p ====
CREATE OR REPLACE VIEW default.view_SG_a_host_payout_flexplus_p2p (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(pe.createdAt, 'Asia/Singapore')) AS month, round(sum(pe.payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_payout_entries AS pe LEFT JOIN default.v_host_mechanism_map AS m ON (m.market = 'SG') AND (m.host_id = pe.hostId) WHERE (pe.payoutType = 'flexplus') AND ((pe.finance_status IS NULL) OR (pe.finance_status != 'Under Review')) AND (pe.tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) AND (ifNull(m.mechanism, 'p2p') = 'p2p') GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== view_SG_a_host_payout_flexplus_rms ====
CREATE OR REPLACE VIEW default.view_SG_a_host_payout_flexplus_rms (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(pe.createdAt, 'Asia/Singapore')) AS month, round(sum(pe.payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_payout_entries AS pe LEFT JOIN default.v_host_mechanism_map AS m ON (m.market = 'SG') AND (m.host_id = pe.hostId) WHERE (pe.payoutType = 'flexplus') AND ((pe.finance_status IS NULL) OR (pe.finance_status != 'Under Review')) AND (pe.tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) AND (ifNull(m.mechanism, 'p2p') = 'rms') GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== view_SG_a_host_payout_regular_rms ====
CREATE OR REPLACE VIEW default.view_SG_a_host_payout_regular_rms (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(pe.createdAt, 'Asia/Singapore')) AS month, round(sum(pe.payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_payout_entries AS pe LEFT JOIN default.v_host_mechanism_map AS m ON (m.market = 'SG') AND (m.host_id = pe.hostId) WHERE ((pe.finance_status IS NULL) OR (pe.finance_status != 'Under Review')) AND (pe.tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) AND (((pe.payoutType IN ('duration', 'distance', 'trip')) AND (ifNull(m.mechanism, 'p2p') = 'rms')) OR (pe.payoutType = 'rms')) GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== view_SG_a_host_referral_payout_new ====
CREATE OR REPLACE VIEW default.view_SG_a_host_referral_payout_new (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType = 'referral') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== view_SG_a_host_rms_payout_new ====
CREATE OR REPLACE VIEW default.view_SG_a_host_rms_payout_new (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) AS month, sum(abs(payoutAmount)) / 100. AS amount, count(*) AS row_count FROM default.sg_payout_entries WHERE (payoutType = 'rms') AND ((finance_status IS NULL) OR (finance_status != 'Under Review')) AND (tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry')) GROUP BY toStartOfMonth(toTimeZone(createdAt, 'Asia/Singapore')) HAVING month < toStartOfMonth(today());

-- ==== view_SG_a_host_trip_earnings_accrual ====
CREATE OR REPLACE VIEW default.view_SG_a_host_trip_earnings_accrual (`month` Nullable(Date), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `transfer_count` UInt64, `unique_trips` UInt64, `transfers_with_app_fees` UInt64) AS SELECT multiIf(toUInt32(JSONExtractUInt(mt.protectedData, 'bookingDisplayEnd') / 1000) > 0, dateTrunc('month', fromUnixTimestamp(toUInt32(JSONExtractUInt(mt.protectedData, 'bookingDisplayEnd') / 1000))), dateTrunc('month', toDateTime(bt.created))) AS month, round(sum((bt.amount + ifNull(af_bt.amount, 0)) / 100.), 2) AS amount, round(sum(bt.fee / 100.), 2) AS fee, round(sum(bt.net / 100.), 2) AS net_amount, count(*) AS transfer_count, countDistinct(JSONExtractString(cm.metadata, 'sharetribe-transaction-id')) AS unique_trips, count(af_bt.source) AS transfers_with_app_fees FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_transfers AS t ON bt.source = t.id LEFT JOIN default.sg_stripe_charges AS c ON t.source_transaction = c.id LEFT JOIN default.sg_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.sg_transactions AS mt ON JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = mt.id LEFT JOIN default.sg_stripe_balance_transactions AS af_bt ON (c.application_fee = af_bt.source) AND (af_bt.reporting_category = 'platform_earning') WHERE bt.reporting_category IN ('transfer', 'transfer_reversal', 'platform_earning', 'platform_earning_refund') GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== view_SG_a_host_trip_earnings_accrual_new ====
CREATE OR REPLACE VIEW default.view_SG_a_host_trip_earnings_accrual_new (`month` Nullable(Date), `total_host_trip_earnings` Nullable(Float64), `payout_count` UInt64, `unique_hosts` UInt64, `unique_trips` UInt64, `duration_earnings` Nullable(Float64), `late_return_earnings` Nullable(Float64), `duration_count` UInt64, `late_return_count` UInt64) AS WITH trip_payouts AS (SELECT pe.id, pe.payoutType, pe.payoutAmount, pe.tripId, pe.hostId, pe.createdAt AS payout_created_at, multiIf((pe.tripId IS NOT NULL) AND (JSONExtractUInt(mt.protectedData, 'bookingDisplayEnd') > 0) AND match(toString(JSONExtractUInt(mt.protectedData, 'bookingDisplayEnd')), '^[0-9]+$'), toStartOfMonth(fromUnixTimestamp(toUInt32(JSONExtractUInt(mt.protectedData, 'bookingDisplayEnd') / 1000))), toStartOfMonth(pe.createdAt)) AS accrual_month FROM default.sg_payout_entries AS pe LEFT JOIN default.sg_transactions AS mt ON pe.tripId = mt.id WHERE (pe.payoutType IN ('duration', 'late_return')) AND ((pe.finance_status != 'Under Review') OR (pe.finance_status IS NULL)) AND (pe.tripStatus NOT IN ('cancelled-refundable', 'payment-failed', 'unverified', 'error', 'enquiry'))) SELECT accrual_month AS month, sum(payoutAmount / 100.) AS total_host_trip_earnings, count(*) AS payout_count, COUNTDistinct(hostId) AS unique_hosts, COUNTDistinct(tripId) AS unique_trips, sum(if(payoutType = 'duration', payoutAmount / 100., 0)) AS duration_earnings, sum(if(payoutType = 'late_return', payoutAmount / 100., 0)) AS late_return_earnings, countIf(payoutType = 'duration') AS duration_count, countIf(payoutType = 'late_return') AS late_return_count FROM trip_payouts WHERE accrual_month IS NOT NULL GROUP BY accrual_month HAVING month < toStartOfMonth(today()) ORDER BY accrual_month DESC;

-- ==== view_SG_a_incidentals_direct_revenue_new ====
CREATE OR REPLACE VIEW default.view_SG_a_incidentals_direct_revenue_new (`month` Nullable(Date), `amount` Nullable(Float64), `charge_count` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(sum(bt.amount) / 100., 2) AS amount, count(*) AS charge_count FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_charges AS c ON bt.source = c.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== view_SG_a_incidentals_invoiced ====
CREATE OR REPLACE VIEW default.view_SG_a_incidentals_invoiced (`month` Nullable(Date), `amount` Nullable(Float64), `amount_paid` Nullable(Float64), `amount_remaining` Nullable(Float64), `invoice_count` UInt64, `paid_invoices` UInt64, `open_invoices` UInt64, `non_invoice_charges` UInt64, `invoice_charges` UInt64, `days_with_invoices` UInt64) AS SELECT month, round(sum(amount), 2) AS amount, round(sum(amount_paid), 2) AS amount_paid, round(sum(amount_remaining), 2) AS amount_remaining, sum(invoice_count) AS invoice_count, sum(paid_invoices) AS paid_invoices, sum(open_invoices) AS open_invoices, sum(non_invoice_charges) AS non_invoice_charges, sum(invoice_charges) AS invoice_charges, uniqExact(invoice_date) AS days_with_invoices FROM (SELECT toStartOfMonth(toDate(i.created)) AS month, i.amount_due / 100. AS amount, i.amount_paid / 100. AS amount_paid, i.amount_remaining / 100. AS amount_remaining, 1 AS invoice_count, if(i.status = 'paid', 1, 0) AS paid_invoices, if(i.status = 'open', 1, 0) AS open_invoices, 0 AS non_invoice_charges, 1 AS invoice_charges, toDate(i.created) AS invoice_date FROM default.sg_stripe_invoices AS i WHERE (i.subscription IS NULL) AND (i.status NOT IN ('void', 'draft')) UNION ALL SELECT toStartOfMonth(toDate(bt.created)) AS month, bt.amount / 100. AS amount, bt.amount / 100. AS amount_paid, 0 AS amount_remaining, 0 AS invoice_count, 0 AS paid_invoices, 0 AS open_invoices, 1 AS non_invoice_charges, 0 AS invoice_charges, toDate(bt.created) AS invoice_date FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_charges AS c ON bt.source = c.id LEFT JOIN default.sg_stripe_charges AS cm ON c.id = cm.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = '') AND (bt.description NOT LIKE '%verification%') AND (bt.description NOT LIKE '%deposit%')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== view_SG_a_misc_ ====
CREATE OR REPLACE VIEW default.view_SG_a_misc_ (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT month, round(sum(payoutAmount / 100.), 2) AS amount, count(*) AS row_count FROM default.v_SG_a_misc_payout_classified WHERE account_code = '5042 residual' GROUP BY month HAVING month < toStartOfMonth(today());

-- ==== view_SG_a_subscription_invoiced ====
CREATE OR REPLACE VIEW default.view_SG_a_subscription_invoiced (`month` Nullable(Date), `amount` Nullable(Float64), `amount_paid` Nullable(Float64), `amount_remaining` Nullable(Float64), `invoice_count` UInt64, `unique_subscriptions` UInt64, `paid_invoices` UInt64, `open_invoices` UInt64, `days_with_invoices` UInt64) AS SELECT toStartOfMonth(toDate(i.created)) AS month, round(sum(i.total / 100.), 2) AS amount, round(sum(i.amount_paid / 100.), 2) AS amount_paid, round(sum(i.amount_remaining / 100.), 2) AS amount_remaining, count(*) AS invoice_count, uniqExact(i.subscription) AS unique_subscriptions, uniqExactIf(i.id, i.status = 'paid') AS paid_invoices, uniqExactIf(i.id, i.status = 'open') AS open_invoices, uniqExact(toDate(i.created)) AS days_with_invoices FROM default.sg_stripe_invoices AS i WHERE (i.subscription IS NOT NULL) AND (i.status NOT IN ('void', 'draft')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== view_SG_a_subscription_payment_plan ====
CREATE OR REPLACE VIEW default.view_SG_a_subscription_payment_plan (`month` Nullable(Date), `amount` Nullable(Float64), `row_count` UInt64) AS SELECT toStartOfMonth(toDate(i.created)) AS month, round(sum(i.total / 100.), 2) AS amount, count(*) AS row_count FROM default.sg_stripe_invoices AS i WHERE (i.subscription IS NOT NULL) AND (i.status NOT IN ('void', 'draft')) AND ((JSONExtractString(i.metadata, 'payment_plan') != '') OR (lower(i.lines) LIKE '%payment plan%')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month DESC;

-- ==== view_SG_a_trip_revenue_earned ====
CREATE OR REPLACE VIEW default.view_SG_a_trip_revenue_earned (`month` Nullable(Date), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `transaction_count` UInt64, `unique_trips` UInt64, `days_with_revenue` UInt64) AS SELECT toStartOfMonth(multiIf(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000) > 0, dateTrunc('month', fromUnixTimestamp(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000))), dateTrunc('month', toDateTime(bt.created)))) AS month, round(sum(bt.amount / 100.), 2) AS amount, round(sum(bt.fee / 100.), 2) AS fee, round(sum(bt.net / 100.), 2) AS net_amount, count(*) AS transaction_count, uniqExact(JSONExtractString(cm.metadata, 'sharetribe-transaction-id')) AS unique_trips, uniqExact(multiIf(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000) > 0, toDate(fromUnixTimestamp(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000))), toDate(bt.created))) AS days_with_revenue FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_charges AS c ON bt.source = c.id INNER JOIN default.sg_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.sg_transactions AS txn ON JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = txn.id WHERE (bt.reporting_category = 'charge') AND (bt.amount > 0) AND (c.invoice IS NULL) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') != '') AND (bt.description NOT LIKE '%deposit%') AND (bt.description NOT LIKE '%verification%') AND ((txn.processName IS NULL) OR (txn.processName != 'fuel-charging')) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== view_SG_c_connect_balance_recon ====
CREATE OR REPLACE VIEW default.view_SG_c_connect_balance_recon (`month` Nullable(Date), `charges_net` Nullable(Float64), `payouts_net` Nullable(Float64), `refunds_net` Nullable(Float64), `fees_net` Nullable(Float64), `adjustments_net` Nullable(Float64), `net_flow` Nullable(Float64), `txn_count` UInt64) AS SELECT toStartOfMonth(toTimeZone(created, 'Asia/Singapore')) AS month, round(sumIf(net / 100., reporting_category = 'charge'), 2) AS charges_net, round(sumIf(net / 100., reporting_category IN ('payout', 'payout_reversal')), 2) AS payouts_net, round(sumIf(net / 100., reporting_category = 'refund'), 2) AS refunds_net, round(sumIf(net / 100., reporting_category = 'fee'), 2) AS fees_net, round(sumIf(net / 100., reporting_category NOT IN ('charge', 'payout', 'payout_reversal', 'refund', 'fee')), 2) AS adjustments_net, round(sum(net / 100.), 2) AS net_flow, count(*) AS txn_count FROM default.sg_stripe_balance_transactions_for_connected_accounts GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== view_SG_c_stripe_with_transaction_details ====
CREATE OR REPLACE VIEW default.view_SG_c_stripe_with_transaction_details (`payment_month` Nullable(Date), `payment_date` Nullable(Date), `balance_transaction_id` String, `payment_amount_sgd` Nullable(Float64), `stripe_fee_sgd` Nullable(Float64), `net_amount_sgd` Nullable(Float64), `stripe_description` Nullable(String), `reporting_category` Nullable(String), `transaction_type` Nullable(String), `charge_id` Nullable(String), `c.invoice` Nullable(String), `charge_description` Nullable(String), `sharetribe_transaction_id` Nullable(String), `mysql_transaction_id` String, `transaction_created` Nullable(DateTime), `processName` Nullable(String), `booking_display_start` Nullable(DateTime), `booking_display_end` Nullable(DateTime), `parent_transaction_id` Nullable(String), `payin_amount_dollars` Nullable(Int32), `payout_amount_dollars` Nullable(Int32), `listingId` Nullable(String), `host_id` Nullable(String), `guest_id` Nullable(String)) AS SELECT toStartOfMonth(toDate(bt.created)) AS payment_month, toDate(bt.created) AS payment_date, bt.id AS balance_transaction_id, bt.amount / 100. AS payment_amount_sgd, bt.fee / 100. AS stripe_fee_sgd, bt.net / 100. AS net_amount_sgd, bt.description AS stripe_description, bt.reporting_category, bt.type AS transaction_type, bt.source AS charge_id, c.invoice, c.description AS charge_description, JSONExtractString(cm.metadata, 'sharetribe-transaction-id') AS sharetribe_transaction_id, txn.id AS mysql_transaction_id, txn.createdAt AS transaction_created, txn.processName, fromUnixTimestamp(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayStart') / 1000)) AS booking_display_start, fromUnixTimestamp(toUInt32(JSONExtractUInt(txn.protectedData, 'bookingDisplayEnd') / 1000)) AS booking_display_end, JSONExtractString(txn.protectedData, 'parentTxId') AS parent_transaction_id, txn.payin_amount AS payin_amount_dollars, txn.payout_amount AS payout_amount_dollars, txn.listingId, txn.providerId AS host_id, txn.customerId AS guest_id FROM default.sg_stripe_balance_transactions AS bt LEFT JOIN default.sg_stripe_charges AS c ON bt.source = c.id LEFT JOIN default.sg_stripe_charges AS cm ON c.id = cm.id LEFT JOIN default.sg_transactions AS txn ON JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = txn.id WHERE bt.created IS NOT NULL ORDER BY bt.created DESC;

-- ==== view_SG_c_subscription_refunds ====
CREATE OR REPLACE VIEW default.view_SG_c_subscription_refunds (`month` Nullable(Date), `amount` Nullable(Float64), `fee` Nullable(Float64), `net_amount` Nullable(Float64), `transaction_count` UInt64, `unique_subscriptions_refunded` UInt64, `days_with_refunds` UInt64) AS SELECT toStartOfMonth(toDate(bt.created)) AS month, round(sum(bt.amount / 100.), 2) AS amount, round(sum(bt.fee / 100.), 2) AS fee, round(sum(bt.net / 100.), 2) AS net_amount, count(*) AS transaction_count, uniqExact(i.subscription) AS unique_subscriptions_refunded, uniqExact(toDate(bt.created)) AS days_with_refunds FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_refunds AS r ON bt.source = r.id INNER JOIN default.sg_stripe_charges AS c ON r.charge = c.id LEFT JOIN default.sg_stripe_invoices AS i ON c.invoice = i.id LEFT JOIN default.sg_stripe_charges AS cm ON c.id = cm.id WHERE (bt.reporting_category = 'refund') AND (bt.amount < 0) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = '') AND (c.invoice IS NOT NULL) AND (i.subscription IS NOT NULL) GROUP BY month HAVING month < toStartOfMonth(today()) ORDER BY month ASC;

-- ==== view_SG_intermediate_non_trip_refunds ====
CREATE OR REPLACE VIEW default.view_SG_intermediate_non_trip_refunds (`bt.id` String, `bt.created` Nullable(DateTime), `bt.amount` Nullable(Decimal(10, 2)), `fee` Nullable(Decimal(10, 2)), `net` Nullable(Decimal(10, 2)), `bt.description` Nullable(String), `source` Nullable(String), `month` Nullable(Date)) AS SELECT bt.id, bt.created, bt.amount, bt.fee, bt.net, bt.description, bt.source, toStartOfMonth(toDate(bt.created)) AS month FROM default.sg_stripe_balance_transactions AS bt INNER JOIN default.sg_stripe_refunds AS r ON bt.source = r.id INNER JOIN default.sg_stripe_charges AS c ON r.charge = c.id LEFT JOIN default.sg_stripe_charges AS cm ON c.id = cm.id WHERE (bt.reporting_category = 'refund') AND (bt.amount < 0) AND (JSONExtractString(cm.metadata, 'sharetribe-transaction-id') = '') AND (lower(bt.description) NOT LIKE '%deposit%');

-- ==== view_core_team_weekly_score ====
CREATE OR REPLACE VIEW default.view_core_team_weekly_score (`c.week_start` Nullable(Date), `email` Nullable(String), `name` Nullable(String), `conversations_actual` UInt64, `calls_made` UInt64, `avg_call_duration_minutes` Float64, `open_conversations` UInt64, `conv_not_touched_1_day` UInt64, `closed_conversations_no_tickets` UInt64, `FCR` Nullable(Float64), `backlog_time` Nullable(Float64), `pct_SLA_under_30min` Nullable(Float64), `SLA_under_30min_pct` UInt64, `pct_conv_not_touched_1_day` Nullable(Float64), `total_hours_spend` Nullable(Float64), `hours_worked` Nullable(Int32), `closed_all` UInt64, `MFTR` Nullable(Float64), `FTR_above_10` Nullable(Float64), `THT_Median` Nullable(Float64), `THT` Nullable(Float64), `THT_above_8hr` Nullable(Float64), `rating_1_2` Float64, `Adherence_score` Nullable(Float32), `Total_score` Float64) AS WITH CTE_conversations_base AS (SELECT toStartOfWeek(created_at, 1) AS week_start, admin_assignee_id, toString(admin_assignee_id) AS admin_id, id AS event_id, state, JSONExtractRaw(ticket, 'id') AS ticket_id, toInt32OrNull(JSONExtractString(statistics, 'time_to_admin_reply')) AS time_to_admin_reply, toInt32OrNull(JSONExtractString(statistics, 'time_to_first_close')) AS time_to_first_close, toInt32OrNull(JSONExtractString(statistics, 'time_to_last_close')) AS time_to_last_close, toInt32OrNull(JSONExtractString(conversation_rating, 'rating')) AS rating, JSONExtractString(JSONExtractRaw(conversation_rating, 'teammate'), 'id') AS rating_teammate_id FROM default.intercom_conversations WHERE (created_at >= toDate('2025-05-26')) AND (JSONExtractString(source, 'delivered_as') IN ('automated', 'customer_initiated'))), CTE_conversations_agg AS (SELECT week_start, admin_id, uniqIf(event_id, time_to_admin_reply >= 0) AS conversations_actual, round((uniqIf(event_id, (time_to_admin_reply / 60) > 10) * 100.) / nullIf(uniqIf(event_id, time_to_admin_reply >= 0), 0), 1) AS FTR_above_10, uniqIf(event_id, time_to_admin_reply >= 86400) AS conv_not_touched_1_day, sum(multiIf(time_to_admin_reply >= 0, time_to_last_close, NULL)) / (12 * 3600) AS total_hours_spend, uniqIf(event_id, (time_to_admin_reply >= 0) AND (state = 'closed')) AS closed_all, round(avg(multiIf((state = 'closed') AND (time_to_first_close >= 0), time_to_first_close, NULL)) / 60, 0) AS THT, round((uniqIf(event_id, (state = 'closed') AND (time_to_first_close >= 0) AND ((time_to_first_close / 3600) > 8)) * 100.) / nullIf(uniqIf(event_id, (state = 'closed') AND (time_to_first_close >= 0)), 0), 0) AS THT_above_8hr, uniqIf(event_id, state != 'closed') AS open_conversations, uniqIf(event_id, (state = 'closed') AND (ticket_id = '') AND (time_to_admin_reply >= 0)) AS closed_conversations_no_tickets, uniqIf(event_id, (state = 'closed') AND (ticket_id = '') AND (time_to_admin_reply >= 0) AND (time_to_first_close <= 1800)) AS SLA_under_30min_pct FROM CTE_conversations_base GROUP BY week_start, admin_id), CTE_MFTR AS (SELECT week_start, admin_id, avg(time_to_admin_reply) / 60 AS median_time_to_reply FROM (SELECT week_start, admin_id, time_to_admin_reply, row_number() OVER (PARTITION BY week_start, admin_id ORDER BY time_to_admin_reply ASC) AS row_num, count(*) OVER (PARTITION BY week_start, admin_id) AS category_count FROM CTE_conversations_base WHERE time_to_admin_reply >= 0) AS sub WHERE (row_num = floor((category_count + 1) / 2)) OR (row_num = ceil((category_count + 1) / 2)) GROUP BY week_start, admin_id), CTE_THT_Median AS (SELECT week_start, admin_id, round(avg(time_to_first_close) / 60, 2) AS THT_Median FROM (SELECT week_start, admin_id, time_to_first_close, row_number() OVER (PARTITION BY week_start, admin_id ORDER BY time_to_first_close ASC) AS row_num, count(*) OVER (PARTITION BY week_start, admin_id) AS category_count FROM CTE_conversations_base WHERE time_to_first_close >= 0) AS sub WHERE (row_num = floor((category_count + 1) / 2)) OR (row_num = ceil((category_count + 1) / 2)) GROUP BY week_start, admin_id), CTE_rating AS (SELECT week_start, rating_teammate_id AS teammate, coalesce(round((uniqIf(event_id, rating IN (1, 2)) * 100.) / nullIf(uniqIf(event_id, rating >= 0), 0), 0), 0) AS rating_1_2 FROM CTE_conversations_base WHERE rating >= 0 GROUP BY week_start, rating_teammate_id), calls AS (SELECT toStartOfWeek(started_at, 1) AS week_start, multiIf(JSONExtractString(JSONExtractString(metadata, 'user'), 'name') != '', JSONExtractString(JSONExtractString(metadata, 'user'), 'name'), 'Not_assigned') AS admin_name, multiIf(JSONExtractString(JSONExtractString(metadata, 'user'), 'email') != '', JSONExtractString(JSONExtractString(metadata, 'user'), 'email'), 'Not_assigned') AS admin_email, COUNTDistinct(id) AS calls_made, round(avg(duration) / 60, 1) AS avg_call_duration_minutes FROM default.aircall_calls WHERE (started_at >= toDate('2025-05-26')) AND (multiIf(JSONExtractString(JSONExtractString(metadata, 'user'), 'email') != '', JSONExtractString(JSONExtractString(metadata, 'user'), 'email'), 'Not_assigned') IN ('seca@drivelah.sg', 'gem@drivelah.sg', 'edelyn@drivelah.sg', 'izzah@drivelah.sg', 'alice@drivelah.sg', 'cheenee@drivelah.sg', 'maricon@drivelah.sg', 'trixie@drivelah.sg', 'decemberlyn@drivemate.au', 'melvin@drivemate.au', 'rheazel@drivemate.au', 'jeremy@drivelah.sg', 'krizia@drivemate.au', 'arwin@drivemate.au', 'neil@drivemate.au', 'ericajane@drivemate.au', 'mary@drivemate.au', 'emmanuel@drivelah.sg', 'jirah@drivemate.au', 'ron@drivemate.au', 'ray@drivemate.au', 'kate@drivemate.au', 'doris@drivelah.sg', 'edgar@drivelah.sg', 'gabriel@drivelah.sg')) GROUP BY week_start, admin_name, admin_email) SELECT c.week_start, email, name, conversations_actual, calls_made, avg_call_duration_minutes, open_conversations, conv_not_touched_1_day, closed_conversations_no_tickets, (closed_conversations_no_tickets / nullIf(conversations_actual, 0)) * 100 AS FCR, ((open_conversations * 100) * (closed_conversations_no_tickets / nullIf(conversations_actual, 0))) / nullIf(closed_conversations_no_tickets, 0) AS backlog_time, (SLA_under_30min_pct / nullIf(conversations_actual, 0)) * 100 AS pct_SLA_under_30min, SLA_under_30min_pct, (conv_not_touched_1_day / nullIf(conversations_actual, 0)) * 100 AS pct_conv_not_touched_1_day, total_hours_spend, hours_worked, closed_all, MFTR, FTR_above_10, THT_Median, THT, THT_above_8hr, rating_1_2, Adherence_score, (((0.25 * coalesce(MFTR_score, 2)) + (0.2 * coalesce(FTR_above_10_score, 2))) + (0.2 * coalesce(THT_score, 2))) + (0.35 * coalesce(rating_1_2_score, 3)) AS Total_score FROM (SELECT c.week_start, ad.email, ad.name, c.conversations_actual, c.conv_not_touched_1_day, c.total_hours_spend, c.closed_all, ad.hours_worked, round(m.median_time_to_reply, 1) AS MFTR, c.FTR_above_10, tm.THT_Median, c.THT, c.THT_above_8hr, r.rating_1_2, ad.Adherence_score, c.open_conversations, c.closed_conversations_no_tickets, c.SLA_under_30min_pct, calls.calls_made, calls.avg_call_duration_minutes, multiIf(round(m.median_time_to_reply, 1) <= 10, 5, (round(m.median_time_to_reply, 1) > 10) AND (round(m.median_time_to_reply, 1) <= 15), 3, round(m.median_time_to_reply, 1) > 15, 1, NULL) AS MFTR_score, multiIf(c.FTR_above_10 <= 10, 5, (c.FTR_above_10 > 10) AND (c.FTR_above_10 <= 20), 3, c.FTR_above_10 > 20, 1, NULL) AS FTR_above_10_score, multiIf(c.THT <= 4, 5, (c.THT > 4) AND (c.THT <= 8), 3, c.THT > 8, 1, NULL) AS THT_score, multiIf(c.THT_above_8hr < 15, 5, (c.THT_above_8hr >= 15) AND (c.THT_above_8hr < 20), 4, (c.THT_above_8hr >= 20) AND (c.THT_above_8hr < 28), 3, (c.THT_above_8hr >= 28) AND (c.THT_above_8hr < 35), 2, c.THT_above_8hr >= 35, 1, NULL) AS THT_above_8hr_score, multiIf(r.rating_1_2 <= 20, 5, (r.rating_1_2 > 20) AND (r.rating_1_2 <= 50), 3, r.rating_1_2 > 50, 1, NULL) AS rating_1_2_score FROM CTE_conversations_agg AS c LEFT JOIN CTE_MFTR AS m ON (c.week_start = m.week_start) AND (c.admin_id = m.admin_id) LEFT JOIN CTE_THT_Median AS tm ON (c.week_start = tm.week_start) AND (c.admin_id = tm.admin_id) LEFT JOIN CTE_rating AS r ON (c.week_start = r.week_start) AND (c.admin_id = r.teammate) LEFT JOIN default.intercom_admins AS ad ON c.admin_id = ad.id LEFT JOIN calls ON (c.week_start = calls.week_start) AND (calls.admin_email = ad.email) WHERE ad.email IN ('seca@drivelah.sg', 'gem@drivelah.sg', 'edelyn@drivelah.sg', 'izzah@drivelah.sg', 'alice@drivelah.sg', 'cheenee@drivelah.sg', 'maricon@drivelah.sg', 'trixie@drivelah.sg', 'decemberlyn@drivemate.au', 'melvin@drivemate.au', 'rheazel@drivemate.au', 'jeremy@drivelah.sg', 'krizia@drivemate.au', 'arwin@drivemate.au', 'neil@drivemate.au', 'ericajane@drivemate.au', 'mary@drivemate.au', 'emmanuel@drivelah.sg', 'jirah@drivemate.au', 'ron@drivemate.au', 'ray@drivemate.au', 'kate@drivemate.au', 'doris@drivelah.sg', 'edgar@drivelah.sg', 'gabriel@drivelah.sg')) ORDER BY c.week_start ASC;
